head.b:skin:
/* ============================================================
   LAPTORIUM v1.0.0 — Toko Laptop & PC + CMS + POS
   Desain: cerah, bersih, modern. Mobile-first, responsif.
   ============================================================ */
:root{
  --bg:#f4f7fe; --surface:#ffffff; --surface-2:#eef3fd;
  --ink:#0e1a33; --muted:#5b6b8c; --faint:#8ea0c2; --line:#e3eaf7;
  --brand:#2563eb; --brand-2:#7c3aed; --brand-dark:#1d4ed8;
  --grad:linear-gradient(135deg,#2563eb 0%,#4f46e5 45%,#7c3aed 100%);
  --grad-soft:linear-gradient(135deg,#dbeafe 0%,#ede9fe 100%);
  --accent:#f59e0b; --success:#16a34a; --success-bg:#dcfce7;
  --danger:#ef4444; --danger-bg:#fee2e2; --warn:#d97706; --warn-bg:#fef3c7;
  --info:#0284c7; --info-bg:#e0f2fe;
  --r-sm:10px; --r:16px; --r-lg:24px; --r-xl:32px;
  --sh-sm:0 2px 10px rgba(37,99,235,.08);
  --sh:0 12px 40px -12px rgba(37,99,235,.22);
  --sh-lg:0 30px 80px -20px rgba(37,99,235,.30);
  --font:'Plus Jakarta Sans',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;
  --nav-h:72px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--font);background:var(--bg);color:var(--ink);line-height:1.65;font-size:16px;overflow-x:hidden}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer}
input,select,textarea{font-family:inherit;font-size:15px}
::selection{background:#bfdbfe}
.skip-link{position:absolute;left:-999px;top:0;background:var(--ink);color:#fff;padding:10px 18px;border-radius:0 0 12px 0;z-index:2000}
.skip-link:focus{left:0}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 20px}
.section{padding:84px 0}
.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--brand);background:#e8effe;border:1px solid #c9d8fb;padding:7px 16px;border-radius:100px;margin-bottom:16px}
.eyebrow i{font-size:12px}
.h2{font-size:clamp(28px,4.5vw,44px);line-height:1.15;font-weight:800;letter-spacing:-.02em;margin-bottom:14px}
.h2 .grad,.grad-text{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.lead{color:var(--muted);font-size:clamp(15px,2vw,18px);max-width:640px}
.center{text-align:center}
.center .lead{margin:0 auto}
/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;font-weight:700;font-size:15px;padding:14px 28px;border-radius:14px;border:1px solid transparent;transition:transform .25s,box-shadow .25s,background .25s;position:relative;overflow:hidden;white-space:nowrap}
.btn:active{transform:scale(.97)}
.btn-primary{background:var(--grad);color:#fff;box-shadow:0 10px 26px -8px rgba(79,70,229,.55)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 36px -8px rgba(79,70,229,.6)}
.btn-primary::after{content:'';position:absolute;top:0;left:-80%;width:50%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.45),transparent);transform:skewX(-20deg);transition:left .6s}
.btn-primary:hover::after{left:130%}
.btn-outline{background:#fff;border-color:#c9d8fb;color:var(--brand-dark)}
.btn-outline:hover{border-color:var(--brand);box-shadow:var(--sh-sm);transform:translateY(-2px)}
.btn-dark{background:var(--ink);color:#fff}
.btn-dark:hover{transform:translateY(-2px);box-shadow:0 14px 30px -10px rgba(14,26,51,.5)}
.btn-success{background:var(--success);color:#fff;box-shadow:0 10px 24px -8px rgba(22,163,74,.5)}
.btn-success:hover{transform:translateY(-2px)}
.btn-danger{background:var(--danger);color:#fff}
.btn-ghost{background:transparent;color:var(--brand-dark)}
.btn-sm{padding:9px 18px;font-size:13.5px;border-radius:10px}
.btn-block{width:100%}
.btn[disabled]{opacity:.55;pointer-events:none}
/* ---------- Announcement + Navbar ---------- */
.announce{background:var(--ink);color:#fff;font-size:13.5px;text-align:center;padding:9px 16px;position:relative;z-index:60}
.announce b{color:#fcd34d}
.announce a{text-decoration:underline;font-weight:700}
.navbar{position:sticky;top:0;z-index:100;height:var(--nav-h);background:rgba(255,255,255,.82);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}
.nav-inner{max-width:1200px;margin:0 auto;padding:0 20px;height:var(--nav-h);display:flex;align-items:center;gap:18px}
.logo{display:flex;align-items:center;gap:11px;font-weight:800;font-size:21px;letter-spacing:-.02em}
.logo-mark{width:42px;height:42px;border-radius:13px;background:var(--grad);display:grid;place-items:center;color:#fff;font-size:19px;box-shadow:0 8px 20px -6px rgba(79,70,229,.6)}
.logo small{display:block;font-size:10.5px;font-weight:700;color:var(--faint);letter-spacing:.14em;line-height:1}
.nav-links{display:flex;gap:4px;margin-left:8px;flex:1}
.nav-links a{font-weight:600;font-size:14.5px;color:var(--muted);padding:10px 14px;border-radius:10px;transition:.2s}
.nav-links a:hover,.nav-links a.active{color:var(--brand-dark);background:#eaf1ff}
.nav-actions{display:flex;align-items:center;gap:10px}
.icon-btn{width:44px;height:44px;border-radius:13px;border:1px solid var(--line);background:#fff;display:grid;place-items:center;font-size:17px;color:var(--ink);position:relative;transition:.2s}
.icon-btn:hover{border-color:var(--brand);color:var(--brand);transform:translateY(-2px);box-shadow:var(--sh-sm)}
.cart-count{position:absolute;top:-7px;right:-7px;min-width:22px;height:22px;padding:0 6px;border-radius:11px;background:var(--grad);color:#fff;font-size:12px;font-weight:800;display:grid;place-items:center;transition:transform .3s}
.cart-count.pop{animation:pop .45s}
@keyframes pop{40%{transform:scale(1.5)}}
.burger{display:none}
/* Mobile menu */
.mmenu{position:fixed;inset:0;z-index:200;pointer-events:none}
.mmenu .scrim{position:absolute;inset:0;background:rgba(14,26,51,.5);opacity:0;transition:.3s}
.mmenu .panel{position:absolute;top:0;right:0;bottom:0;width:min(340px,88vw);background:#fff;padding:22px;transform:translateX(105%);transition:transform .35s cubic-bezier(.2,.8,.25,1);overflow-y:auto}
.mmenu.open{pointer-events:auto}
.mmenu.open .scrim{opacity:1}
.mmenu.open .panel{transform:none}
.mmenu a.mlink{display:flex;align-items:center;gap:12px;padding:13px 14px;border-radius:12px;font-weight:700;color:var(--ink)}
.mmenu a.mlink i{width:34px;height:34px;border-radius:10px;background:var(--surface-2);display:grid;place-items:center;color:var(--brand)}
.mmenu a.mlink:hover{background:var(--surface-2)}
/* ---------- Hero ---------- */
.hero{position:relative;overflow:hidden;background:linear-gradient(180deg,#eaf1ff 0%,var(--bg) 100%)}
.hero::before,.hero::after{content:'';position:absolute;border-radius:50%;filter:blur(90px);opacity:.55;pointer-events:none}
.hero::before{width:480px;height:480px;background:#bfdbfe;top:-160px;left:-140px;animation:drift 14s ease-in-out infinite alternate}
.hero::after{width:520px;height:520px;background:#ddd6fe;bottom:-220px;right:-160px;animation:drift 18s ease-in-out infinite alternate-reverse}
@keyframes drift{to{transform:translate(60px,40px) scale(1.08)}}
.hero-inner{position:relative;z-index:2;display:grid;grid-template-columns:1.05fr .95fr;gap:48px;align-items:center;padding:72px 0 88px}
.hero h1{font-size:clamp(34px,5.6vw,60px);line-height:1.08;font-weight:800;letter-spacing:-.025em;margin:18px 0 16px}
.hero p.sub{color:var(--muted);font-size:clamp(15px,2.2vw,18.5px);max-width:540px;margin-bottom:28px}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:30px}
.hero-points{display:flex;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:14px;font-weight:600}
.hero-points span{display:flex;align-items:center;gap:8px}
.hero-points i{color:var(--success)}
.hero-stats{display:flex;gap:36px;margin-top:30px;flex-wrap:wrap}
.hstat b{display:block;font-size:26px;font-weight:800}
.hstat span{font-size:13.5px;color:var(--muted);font-weight:600}
.hero-visual{position:relative}
.hero-img-card{position:relative;border-radius:var(--r-xl);overflow:hidden;box-shadow:var(--sh-lg);border:6px solid #fff;transform:rotate(1.5deg)}
.hero-img-card img{width:100%;height:420px;object-fit:cover}
.float-card{position:absolute;background:rgba(255,255,255,.9);backdrop-filter:blur(12px);border:1px solid #fff;border-radius:18px;padding:13px 16px;box-shadow:var(--sh);display:flex;gap:12px;align-items:center;animation:floaty 5s ease-in-out infinite}
.float-card .fi{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;color:#fff;font-size:18px;flex:none}
.float-card b{display:block;font-size:14px;line-height:1.3}
.float-card small{color:var(--muted);font-size:12.5px;font-weight:600}
.fc-1{top:26px;left:-34px}
.fc-2{bottom:44px;right:-22px;animation-delay:1.4s}
.fc-3{bottom:-24px;left:34px;animation-delay:2.6s}
@keyframes floaty{50%{transform:translateY(-12px)}}
.hero-badge-rotate{position:absolute;top:-28px;right:8px;width:104px;height:104px;z-index:3;animation:spin 16s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
/* ---------- Marquee brands ---------- */
.brands{background:#fff;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:22px 0;overflow:hidden}
.marquee{display:flex;gap:56px;width:max-content;animation:scrollX 26s linear infinite;font-weight:800;color:#9fb0d0;font-size:19px;letter-spacing:.02em}
.marquee i{margin-right:9px;color:#c3cfe8}
@keyframes scrollX{to{transform:translateX(-50%)}}
/* ---------- Features ---------- */
.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px}
.feat{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:30px 26px;position:relative;overflow:hidden;transition:transform .3s,box-shadow .3s}
.feat::before{content:'';position:absolute;inset:0 0 auto 0;height:4px;background:var(--grad);opacity:0;transition:.3s}
.feat:hover{transform:translateY(-8px);box-shadow:var(--sh)}
.feat:hover::before{opacity:1}
.feat-ic{width:58px;height:58px;border-radius:17px;background:var(--grad-soft);display:grid;place-items:center;font-size:24px;margin-bottom:18px}
.feat h3{font-size:18px;margin-bottom:8px}
.feat p{color:var(--muted);font-size:14.5px}
/* ---------- Katalog ---------- */
.shop-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;flex-wrap:wrap}
.cat-pills{display:flex;gap:10px;flex-wrap:wrap;margin:26px 0 18px}
.pill{border:1.5px solid var(--line);background:#fff;padding:10px 20px;border-radius:100px;font-weight:700;font-size:14px;color:var(--muted);transition:.2s}
.pill:hover{border-color:var(--brand);color:var(--brand)}
.pill.active{background:var(--ink);border-color:var(--ink);color:#fff;box-shadow:0 8px 20px -8px rgba(14,26,51,.5)}
.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px}
.searchbox{flex:1;min-width:220px;display:flex;align-items:center;gap:10px;background:#fff;border:1.5px solid var(--line);border-radius:13px;padding:0 16px;transition:.2s}
.searchbox:focus-within{border-color:var(--brand);box-shadow:0 0 0 4px #dbeafe}
.searchbox input{border:0;outline:0;flex:1;padding:13px 0;background:transparent}
.searchbox i{color:var(--faint)}
.select{border:1.5px solid var(--line);border-radius:13px;padding:12px 16px;background:#fff;font-weight:600;color:var(--ink);outline:0}
.pgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.pcard{background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;transition:transform .3s,box-shadow .3s;display:flex;flex-direction:column}
.pcard:hover{transform:translateY(-8px);box-shadow:var(--sh)}
.pcard-img{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--surface-2)}
.pcard-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.pcard:hover .pcard-img img{transform:scale(1.07)}
.pbadge{position:absolute;top:12px;left:12px;background:var(--grad);color:#fff;font-size:12px;font-weight:800;padding:5px 12px;border-radius:100px;box-shadow:0 6px 14px -4px rgba(79,70,229,.6)}
.pbadge.second{background:linear-gradient(135deg,#059669,#10b981)}
.pwish{position:absolute;top:10px;right:10px;width:36px;height:36px;border-radius:50%;border:0;background:rgba(255,255,255,.92);color:#94a3b8;font-size:15px;display:grid;place-items:center;transition:.2s}
.pwish.loved{color:#e11d48}
.pstock{position:absolute;bottom:12px;left:12px;font-size:12px;font-weight:800;padding:5px 12px;border-radius:100px;background:rgba(255,255,255,.94)}
.pstock.ok{color:var(--success)} .pstock.low{color:var(--warn)} .pstock.out{color:var(--danger)}
.pcard-body{padding:18px;display:flex;flex-direction:column;gap:8px;flex:1}
.pcat{font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--brand)}
.pname{font-size:15.5px;font-weight:700;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:44px}
.pspec{font-size:13px;color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.prate{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--muted);font-weight:600}
.prate .stars{color:#f59e0b;letter-spacing:1px}
.pprice{margin-top:auto;padding-top:6px;display:flex;align-items:baseline;gap:9px;flex-wrap:wrap}
.pprice .now{font-size:19px;font-weight:800;color:var(--brand-dark)}
.pprice .was{font-size:13.5px;color:var(--faint);text-decoration:line-through}
.pdisc{background:#fee2e2;color:#dc2626;font-size:12px;font-weight:800;padding:3px 9px;border-radius:8px}
.pcard-actions{display:flex;gap:9px;margin-top:8px}
.pcard-actions .btn{flex:1;padding:11px 8px;font-size:13.5px;border-radius:11px}
/* Skeleton */
.sk{background:linear-gradient(90deg,#e8eefb 25%,#f5f8ff 50%,#e8eefb 75%);background-size:200% 100%;animation:sk 1.2s infinite;border-radius:12px}
@keyframes sk{to{background-position:-200% 0}}
/* ---------- Promo banner ---------- */
.promo-slider{position:relative;border-radius:var(--r-xl);overflow:hidden;box-shadow:var(--sh-lg);margin-top:44px}
.pslide{display:none;position:relative;min-height:300px;color:#fff}
.pslide.active{display:block;animation:fadeSlide .6s}
@keyframes fadeSlide{from{opacity:0;transform:scale(1.02)}}
.pslide img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.pslide .overlay{position:absolute;inset:0;background:linear-gradient(100deg,rgba(14,26,51,.88) 20%,rgba(37,99,235,.55) 60%,transparent)}
.pslide .txt{position:relative;z-index:2;padding:56px 48px;max-width:620px}
.pslide h3{font-size:clamp(24px,4vw,38px);font-weight:800;margin-bottom:10px}
.pslide p{opacity:.9;margin-bottom:22px}
.pdots{position:absolute;bottom:18px;left:48px;display:flex;gap:8px;z-index:3}
.pdots button{width:34px;height:6px;border-radius:4px;border:0;background:rgba(255,255,255,.35);transition:.3s}
.pdots button.active{background:#fff;width:52px}
/* ---------- Layanan ---------- */
.svc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:44px}
.svc{background:#0e1a33;color:#e6ecf8;border-radius:var(--r-lg);padding:32px 28px;position:relative;overflow:hidden;transition:transform .3s}
.svc::after{content:'';position:absolute;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,rgba(124,58,237,.35),transparent 70%);top:-80px;right:-80px}
.svc:hover{transform:translateY(-8px)}
.svc-ic{font-size:38px;margin-bottom:16px;position:relative;z-index:2}
.svc h3{font-size:19px;margin-bottom:8px;position:relative;z-index:2}
.svc p{font-size:14px;color:#a9b8d8;margin-bottom:16px;position:relative;z-index:2}
.svc ul{list-style:none;margin-bottom:18px;position:relative;z-index:2}
.svc li{font-size:13.5px;padding:5px 0;color:#cdd8ef}
.svc li i{color:#34d399;margin-right:9px}
.svc .price{font-weight:800;color:#fcd34d;position:relative;z-index:2}
/* ---------- Benefit / Kenapa kami ---------- */
.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
.split-img{position:relative}
.split-img img.main{border-radius:var(--r-xl);box-shadow:var(--sh-lg);height:480px;width:100%;object-fit:cover}
.exp-card{position:absolute;bottom:-26px;right:-16px;background:var(--grad);color:#fff;border-radius:20px;padding:22px 30px;text-align:center;box-shadow:var(--sh-lg)}
.exp-card b{font-size:34px;display:block;line-height:1}
.check-list{list-style:none;margin:24px 0}
.check-list li{display:flex;gap:14px;padding:13px 0;border-bottom:1px dashed var(--line)}
.check-list .ck{width:30px;height:30px;flex:none;border-radius:50%;background:var(--success-bg);color:var(--success);display:grid;place-items:center;font-size:14px;margin-top:2px}
.check-list b{display:block;font-size:15.5px}
.check-list span{color:var(--muted);font-size:14px}
.guarantee{display:flex;gap:16px;background:#fff;border:2px dashed #bfdbfe;border-radius:var(--r-lg);padding:20px;margin-top:8px;align-items:center}
.guarantee .gi{width:56px;height:56px;flex:none;border-radius:16px;background:var(--grad);color:#fff;display:grid;place-items:center;font-size:24px}
/* ---------- Tukar tambah ---------- */
.trade{background:linear-gradient(135deg,#0e1a33,#1e1b4b);border-radius:var(--r-xl);padding:56px;color:#fff;position:relative;overflow:hidden}
.trade::before{content:'';position:absolute;width:420px;height:420px;background:radial-gradient(circle,rgba(124,58,237,.4),transparent 70%);top:-140px;right:-100px}
.trade-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;position:relative;z-index:2}
.steps{margin-top:26px;display:flex;flex-direction:column;gap:4px}
.step{display:flex;gap:16px;padding:14px 0}
.step .n{width:40px;height:40px;flex:none;border-radius:50%;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);display:grid;place-items:center;font-weight:800}
.tform{background:#fff;color:var(--ink);border-radius:var(--r-lg);padding:30px;box-shadow:var(--sh-lg)}
.tform h3{margin-bottom:4px}
.tform p{font-size:14px;color:var(--muted);margin-bottom:18px}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.field{margin-bottom:13px}
.field label{display:block;font-size:13px;font-weight:700;margin-bottom:6px;color:var(--ink)}
.field input,.field select,.field textarea{width:100%;border:1.5px solid var(--line);border-radius:11px;padding:11px 14px;outline:0;background:#f8faff;transition:.2s;color:var(--ink)}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--brand);box-shadow:0 0 0 4px #dbeafe;background:#fff}
.field textarea{resize:vertical;min-height:90px}
/* ---------- Testimoni ---------- */
.tst-wrap{position:relative;margin-top:44px}
.tst-track{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.tst{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:28px;display:flex;flex-direction:column;gap:14px;transition:transform .3s,box-shadow .3s}
.tst:hover{transform:translateY(-6px);box-shadow:var(--sh)}
.tst .stars{color:#f59e0b;letter-spacing:2px;font-size:14px}
.tst p{font-size:14.5px;color:#33415e;flex:1}
.tst-who{display:flex;gap:12px;align-items:center}
.avatar{width:48px;height:48px;border-radius:50%;background:var(--grad);color:#fff;display:grid;place-items:center;font-weight:800;font-size:17px;flex:none}
.tst-who b{display:block;font-size:14.5px}
.tst-who span{font-size:13px;color:var(--muted)}
.gsum{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:30px;flex-wrap:wrap;background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px 28px}
.gsum .big{font-size:40px;font-weight:800}
.gsum .stars{color:#f59e0b;font-size:18px;letter-spacing:3px}
/* ---------- FAQ ---------- */
.faq-list{max-width:780px;margin:36px auto 0;display:flex;flex-direction:column;gap:13px}
.faq{background:#fff;border:1.5px solid var(--line);border-radius:16px;overflow:hidden;transition:.25s}
.faq.open{border-color:var(--brand);box-shadow:var(--sh-sm)}
.faq-q{width:100%;background:none;border:0;display:flex;justify-content:space-between;align-items:center;gap:14px;padding:19px 22px;font-weight:700;font-size:15.5px;text-align:left;color:var(--ink)}
.faq-q .fx{width:32px;height:32px;flex:none;border-radius:50%;background:var(--surface-2);display:grid;place-items:center;color:var(--brand);transition:.3s;font-size:14px}
.faq.open .fx{transform:rotate(45deg);background:var(--grad);color:#fff}
.faq-a{max-height:0;overflow:hidden;transition:max-height .4s ease;color:var(--muted);font-size:14.5px}
.faq-a div{padding:0 22px 20px}
/* ---------- CTA ---------- */
.cta-band{background:var(--grad);border-radius:var(--r-xl);padding:64px 48px;text-align:center;color:#fff;position:relative;overflow:hidden;box-shadow:var(--sh-lg)}
.cta-band::before,.cta-band::after{content:'';position:absolute;border-radius:50%;background:rgba(255,255,255,.1)}
.cta-band::before{width:280px;height:280px;top:-120px;left:-90px}
.cta-band::after{width:340px;height:340px;bottom:-170px;right:-110px}
.cta-band h2{font-size:clamp(26px,4.5vw,40px);margin-bottom:12px;position:relative;z-index:2}
.cta-band p{opacity:.92;margin-bottom:28px;position:relative;z-index:2}
.cta-band .row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;position:relative;z-index:2}
.btn-white{background:#fff;color:var(--brand-dark)}
.btn-white:hover{transform:translateY(-2px);box-shadow:0 16px 34px -10px rgba(0,0,0,.35)}
.btn-outline-w{background:transparent;border:2px solid rgba(255,255,255,.6);color:#fff}
.btn-outline-w:hover{border-color:#fff;background:rgba(255,255,255,.12)}
/* ---------- Footer ---------- */
footer{background:var(--ink);color:#b9c5df;margin-top:90px}
.f-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:36px;padding:64px 0 40px}
.f-brand .logo{color:#fff;margin-bottom:14px}
.f-brand p{font-size:14px;margin-bottom:18px}
.soc{display:flex;gap:10px}
.soc a{width:40px;height:40px;border-radius:12px;background:rgba(255,255,255,.08);display:grid;place-items:center;color:#fff;transition:.2s}
.soc a:hover{background:var(--grad);transform:translateY(-3px)}
footer h4{color:#fff;font-size:15px;margin-bottom:16px}
footer ul{list-style:none}
footer ul a,footer ul li{font-size:14px;padding:5px 0;display:block}
footer ul a:hover{color:#fff;padding-left:4px}
footer ul a,footer .fi{transition:.2s}
.f-contact li{display:flex;gap:11px;align-items:flex-start}
.f-contact i{color:#818cf8;margin-top:5px}
.f-bottom{border-top:1px solid rgba(255,255,255,.1);padding:20px 0;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:13.5px}
.f-bottom a{color:#818cf8;font-weight:700}
/* ---------- Floating ---------- */
.fab-wa{position:fixed;bottom:24px;right:24px;z-index:150;width:60px;height:60px;border-radius:50%;background:#22c55e;color:#fff;font-size:28px;display:grid;place-items:center;box-shadow:0 14px 34px -6px rgba(34,197,94,.6);transition:.25s;border:0}
.fab-wa:hover{transform:scale(1.1) rotate(6deg)}
.fab-wa::before{content:'';position:absolute;inset:-5px;border-radius:50%;border:2px solid #22c55e;opacity:.5;animation:ring 2s infinite}
@keyframes ring{to{transform:scale(1.25);opacity:0}}
.fab-cart{position:fixed;bottom:96px;right:24px;z-index:150;display:none}
.mobilenav{display:none}
/* ---------- Drawer cart ---------- */
.scrim{position:fixed;inset:0;background:rgba(14,26,51,.55);z-index:300;opacity:0;pointer-events:none;transition:.3s}
.scrim.show{opacity:1;pointer-events:auto}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(430px,94vw);background:#fff;z-index:301;display:flex;flex-direction:column;transform:translateX(105%);transition:transform .38s cubic-bezier(.2,.8,.25,1);box-shadow:-20px 0 60px rgba(14,26,51,.2)}
.drawer.open{transform:none}
.drawer-h{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}
.drawer-h h3{font-size:18px}
.drawer-b{flex:1;overflow-y:auto;padding:18px 22px;display:flex;flex-direction:column;gap:14px}
.drawer-f{border-top:1px solid var(--line);padding:18px 22px;background:#f8faff}
.citem{display:flex;gap:13px;background:#fff;border:1px solid var(--line);border-radius:15px;padding:12px}
.citem img{width:74px;height:74px;object-fit:cover;border-radius:11px;flex:none}
.citem .ci{flex:1;min-width:0}
.citem b{font-size:13.5px;display:block;line-height:1.35}
.citem .cp{font-size:13px;color:var(--brand-dark);font-weight:800;margin:3px 0 8px}
.qty{display:inline-flex;align-items:center;gap:0;border:1.5px solid var(--line);border-radius:10px;overflow:hidden}
.qty button{width:30px;height:30px;border:0;background:var(--surface-2);font-weight:800;color:var(--brand-dark)}
.qty button:hover{background:#dbeafe}
.qty span{min-width:34px;text-align:center;font-weight:800;font-size:14px}
.citem .rm{align-self:flex-start;border:0;background:none;color:#c3cfe8;font-size:16px}
.citem .rm:hover{color:var(--danger)}
.trow{display:flex;justify-content:space-between;font-size:14px;padding:4px 0;color:var(--muted);font-weight:600}
.trow.grand{font-size:18px;color:var(--ink);font-weight:800;border-top:1px dashed var(--line);margin-top:8px;padding-top:12px}
.empty{text-align:center;padding:48px 10px;color:var(--muted)}
.empty i{font-size:52px;color:#cbd5e1;margin-bottom:14px}
/* ---------- Modal ---------- */
.modal{position:fixed;inset:0;z-index:400;display:grid;place-items:center;padding:18px;pointer-events:none}
.modal .mbox{background:#fff;border-radius:24px;width:100%;max-width:560px;max-height:92vh;overflow-y:auto;padding:30px;transform:translateY(26px) scale(.97);opacity:0;transition:.32s cubic-bezier(.2,.8,.25,1);position:relative}
.modal.open{pointer-events:auto}
.modal.open .mbox{transform:none;opacity:1}
.modal-lg .mbox{max-width:880px}
.mx{position:absolute;top:16px;right:16px;width:38px;height:38px;border-radius:50%;border:0;background:var(--surface-2);font-size:16px;color:var(--muted)}
.mx:hover{background:var(--danger-bg);color:var(--danger)}
.qv-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px}
.qv-grid img.main{border-radius:16px;aspect-ratio:1;object-fit:cover;width:100%}
.qv-thumbs{display:flex;gap:8px;margin-top:10px}
.qv-thumbs img{width:60px;height:60px;object-fit:cover;border-radius:10px;border:2px solid transparent;cursor:pointer}
.qv-thumbs img.sel{border-color:var(--brand)}
.pay-opts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:6px 0 4px}
.pay-opts button{border:2px solid var(--line);background:#fff;border-radius:13px;padding:13px 8px;font-weight:700;font-size:13.5px;display:flex;flex-direction:column;gap:6px;align-items:center;color:var(--muted);transition:.2s}
.pay-opts button i{font-size:21px}
.pay-opts button.sel{border-color:var(--brand);background:#eff6ff;color:var(--brand-dark);box-shadow:0 0 0 3px #dbeafe}
/* ---------- Toast ---------- */
#toasts{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:500;display:flex;flex-direction:column;gap:10px;align-items:center;width:max-content;max-width:92vw}
.toast{background:var(--ink);color:#fff;padding:14px 22px;border-radius:14px;font-weight:600;font-size:14.5px;display:flex;gap:11px;align-items:center;box-shadow:0 16px 40px rgba(14,26,51,.4);animation:tin .35s cubic-bezier(.2,.9,.3,1.2);max-width:92vw}
.toast.success{background:#15803d}.toast.error{background:#b91c1c}.toast.warn{background:#b45309}
@keyframes tin{from{transform:translateY(20px);opacity:0}}
.toast.out{transition:.3s;opacity:0;transform:translateY(10px)}
/* ---------- Reveal anim ---------- */
.rv{opacity:0;transform:translateY(34px);transition:opacity .7s ease,transform .7s cubic-bezier(.2,.7,.3,1)}
.rv.in{opacity:1;transform:none}
.rv-l{opacity:0;transform:translateX(-44px);transition:all .8s cubic-bezier(.2,.7,.3,1)}
.rv-r{opacity:0;transform:translateX(44px);transition:all .8s cubic-bezier(.2,.7,.3,1)}
.rv-l.in,.rv-r.in{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms !important;transition-duration:.01ms !important}.rv,.rv-l,.rv-r{opacity:1;transform:none}}
/* ---------- Views ---------- */
.view{display:none}
body[data-route='store'] #view-store{display:block}
body[data-route='admin'] #view-admin{display:block}
body[data-route='pos'] #view-pos{display:block}
body[data-route='lacak'] #view-lacak{display:block}
body[data-route='admin'] .navbar,body[data-route='pos'] .navbar,body[data-route='admin'] .announce,body[data-route='pos'] .announce,body[data-route='admin'] footer.store-foot,body[data-route='pos'] footer.store-foot,body[data-route='admin'] .fab-wa,body[data-route='pos'] .fab-wa,body[data-route='lacak'] .fab-wa{display:none}
/* ---------- ADMIN ---------- */
.admin-shell{display:grid;grid-template-columns:264px 1fr;min-height:100vh;background:#eef2fa}
.aside{background:var(--ink);color:#b9c5df;display:flex;flex-direction:column;position:sticky;top:0;height:100vh;overflow-y:auto}
.aside .logo{color:#fff;padding:22px 22px 16px}
.amenu{padding:8px 14px 20px;display:flex;flex-direction:column;gap:3px;flex:1}
.amenu .cap{font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#5b6b8c;padding:14px 12px 7px}
.amenu a{display:flex;align-items:center;gap:12px;padding:11px 13px;border-radius:12px;font-weight:600;font-size:14.5px;transition:.2s}
.amenu a i{width:34px;height:34px;flex:none;border-radius:10px;background:rgba(255,255,255,.07);display:grid;place-items:center;font-size:15px}
.amenu a:hover{background:rgba(255,255,255,.07);color:#fff}
.amenu a.active{background:var(--grad);color:#fff;box-shadow:0 10px 24px -8px rgba(79,70,229,.7)}
.amenu a .bdg{margin-left:auto;background:#ef4444;color:#fff;font-size:11px;font-weight:800;min-width:22px;height:22px;border-radius:11px;display:grid;place-items:center;padding:0 7px}
.abody{min-width:0;display:flex;flex-direction:column}
.atop{background:rgba(255,255,255,.85);backdrop-filter:blur(14px);border-bottom:1px solid var(--line);padding:14px 28px;display:flex;align-items:center;gap:14px;position:sticky;top:0;z-index:50}
.atop h2{font-size:19px;flex:1}
.atop .who{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700}
.apage{padding:28px;display:none}
.apage.active{display:block;animation:fadeSlide .4s}
.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}
.stat{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;display:flex;gap:15px;align-items:center;transition:.25s}
.stat:hover{transform:translateY(-3px);box-shadow:var(--sh-sm)}
.stat .si{width:54px;height:54px;flex:none;border-radius:15px;display:grid;place-items:center;font-size:22px;color:#fff}
.stat b{font-size:21px;display:block;line-height:1.2}
.stat span{font-size:13px;color:var(--muted);font-weight:600}
.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:22px}
.card h3{font-size:16.5px;margin-bottom:4px}
.card .sub{font-size:13.5px;color:var(--muted);margin-bottom:16px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px}
table.tbl{width:100%;border-collapse:collapse;font-size:14px;min-width:640px}
.tbl th{background:#f1f5fd;text-align:left;padding:12px 14px;font-size:12.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);white-space:nowrap}
.tbl td{padding:12px 14px;border-top:1px solid var(--line);vertical-align:middle}
.tbl tr:hover td{background:#f8faff}
.tbl img.thumb{width:52px;height:52px;object-fit:cover;border-radius:10px}
.badge{display:inline-block;font-size:12px;font-weight:800;padding:4px 12px;border-radius:100px;white-space:nowrap}
.b-green{background:var(--success-bg);color:#15803d}.b-red{background:var(--danger-bg);color:#b91c1c}
.b-amber{background:var(--warn-bg);color:#b45309}.b-blue{background:#dbeafe;color:#1d4ed8}
.b-purple{background:#ede9fe;color:#6d28d9}.b-gray{background:#e2e8f0;color:#475569}
.rowbtns{display:flex;gap:7px}
.mini-btn{width:34px;height:34px;border-radius:10px;border:1px solid var(--line);background:#fff;display:grid;place-items:center;font-size:14px;color:var(--muted);transition:.2s}
.mini-btn:hover{transform:translateY(-2px)}
.mini-btn.edit:hover{border-color:var(--brand);color:var(--brand)}
.mini-btn.del:hover{border-color:var(--danger);color:var(--danger);background:var(--danger-bg)}
.mini-btn.view:hover{border-color:var(--success);color:var(--success)}
.atoolbar{display:flex;gap:11px;flex-wrap:wrap;margin-bottom:16px;align-items:center}
.atoolbar .searchbox{max-width:320px}
.login-wrap{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#dbeafe,#ede9fe);padding:20px}
.login-card{background:#fff;border-radius:26px;padding:40px 36px;width:100%;max-width:420px;box-shadow:var(--sh-lg);text-align:center}
.login-card .logo{justify-content:center;margin-bottom:8px}
/* ---------- POS ---------- */
.pos-shell{height:100vh;display:flex;flex-direction:column;background:#eef2fa}
.pos-top{background:var(--ink);color:#fff;padding:12px 22px;display:flex;align-items:center;gap:14px}
.pos-top .logo{color:#fff;font-size:17px}
.pos-top .logo-mark{width:36px;height:36px;font-size:16px}
.pos-clock{margin-left:auto;text-align:right;font-size:13px;line-height:1.4}
.pos-clock b{font-size:16px}
.pos-main{flex:1;display:grid;grid-template-columns:1fr 400px;gap:16px;padding:16px;min-height:0}
.pos-left{display:flex;flex-direction:column;gap:13px;min-height:0}
.pos-cats{display:flex;gap:9px;overflow-x:auto;padding-bottom:4px}
.pos-cats .pill{white-space:nowrap;padding:9px 17px;font-size:13.5px}
.pos-grid{flex:1;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(158px,1fr));gap:12px;align-content:start;padding-right:2px}
.pos-item{background:#fff;border:2px solid var(--line);border-radius:16px;padding:11px;text-align:left;transition:.2s;display:flex;flex-direction:column;gap:7px}
.pos-item:hover{border-color:var(--brand);transform:translateY(-3px);box-shadow:var(--sh-sm)}
.pos-item img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px}
.pos-item b{font-size:13px;line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:36px}
.pos-item .pp{font-weight:800;color:var(--brand-dark);font-size:14px}
.pos-item .ps{font-size:11.5px;font-weight:700;color:var(--muted)}
.pos-item.out{opacity:.55}
.pos-cart{background:#fff;border:1px solid var(--line);border-radius:20px;display:flex;flex-direction:column;min-height:0;overflow:hidden}
.pos-cart-h{padding:16px 18px;border-bottom:1px solid var(--line);background:#f8faff}
.pos-cart-items{flex:1;overflow-y:auto;padding:14px 16px;display:flex;flex-direction:column;gap:10px}
.pos-cart-f{border-top:1px solid var(--line);padding:16px 18px;background:#f8faff;display:flex;flex-direction:column;gap:10px}
.pos-total{display:flex;justify-content:space-between;align-items:center;font-size:20px;font-weight:800}
.pos-cash-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.pos-cash-grid button{border:1.5px solid var(--line);background:#fff;border-radius:10px;padding:9px 4px;font-weight:800;font-size:12.5px;color:var(--brand-dark)}
.pos-cash-grid button:hover{border-color:var(--brand);background:#eff6ff}
.kembalian{background:var(--success-bg);border-radius:12px;padding:11px 15px;display:flex;justify-content:space-between;font-weight:800;color:#15803d;font-size:16px}
/* Receipt print */
.receipt{font-family:'Courier New',monospace;font-size:13.5px;color:#111;max-width:300px;margin:0 auto}
.receipt h4{text-align:center;margin-bottom:2px;font-family:var(--font)}
.receipt .c{text-align:center}
.receipt hr{border:0;border-top:1px dashed #999;margin:9px 0}
/* ---------- Lacak ---------- */
.track-card{max-width:640px;margin:40px auto;background:#fff;border-radius:24px;padding:36px;box-shadow:var(--sh)}
.timeline{margin-top:22px;display:flex;flex-direction:column}
.tstep{display:flex;gap:15px;position:relative;padding-bottom:26px}
.tstep::before{content:'';position:absolute;left:19px;top:42px;bottom:0;width:2px;background:var(--line)}
.tstep:last-child::before{display:none}
.tstep .dot{width:40px;height:40px;flex:none;border-radius:50%;background:#e2e8f0;color:#94a3b8;display:grid;place-items:center;z-index:2}
.tstep.done .dot{background:var(--success);color:#fff}
.tstep b{display:block}
/* ---------- Responsive ---------- */
@media(max-width:1080px){
  .pgrid{grid-template-columns:repeat(3,1fr)}
  .stat-grid{grid-template-columns:repeat(2,1fr)}
  .pos-main{grid-template-columns:1fr 340px}
}
@media(max-width:920px){
  .nav-links{display:none}
  .nav-cta{display:none}
  .burger{display:grid}
  .hero-inner{grid-template-columns:1fr;gap:40px;padding:52px 0 70px}
  .hero-img-card img{height:300px}
  .fc-1{left:6px}.fc-2{right:6px}
  .feat-grid,.svc-grid,.tst-track{grid-template-columns:1fr 1fr}
  .split,.trade-grid,.qv-grid{grid-template-columns:1fr}
  .split-img img.main{height:320px}
  .f-grid{grid-template-columns:1fr 1fr}
  .admin-shell{grid-template-columns:1fr}
  .aside{position:fixed;z-index:300;left:0;top:0;bottom:0;width:280px;transform:translateX(-105%);transition:.3s;height:100vh}
  .aside.open{transform:none}
  .apage{padding:18px}
  .pos-main{grid-template-columns:1fr;overflow-y:auto}
  .pos-cart{min-height:480px}
  .grid2{grid-template-columns:1fr}
  .trade{padding:36px 24px}
  .tform{padding:22px}
}
@media(max-width:640px){
  .section{padding:60px 0}
  .pgrid{grid-template-columns:repeat(2,1fr);gap:13px}
  .pcard-body{padding:13px}
  .pname{font-size:13.5px;min-height:38px}
  .pprice .now{font-size:16px}
  .pcard-actions{flex-direction:column}
  .feat-grid,.svc-grid,.tst-track{grid-template-columns:1fr}
  .stat-grid{grid-template-columns:1fr 1fr;gap:11px}
  .stat b{font-size:17px}
  .frow{grid-template-columns:1fr}
  .hero-stats{gap:22px}
  .pslide .txt{padding:36px 24px}
  .cta-band{padding:44px 24px}
  .f-grid{grid-template-columns:1fr}
  .pay-opts{grid-template-columns:repeat(3,1fr)}
  .fab-cart{display:grid;position:fixed;z-index:150;bottom:96px;right:16px;width:58px;height:58px;border-radius:50%;background:var(--grad);color:#fff;font-size:22px;border:0;box-shadow:var(--sh-lg)}
  .fab-wa{width:54px;height:54px;font-size:24px;bottom:24px;right:16px}
  .mobilenav{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:140;background:rgba(255,255,255,.94);backdrop-filter:blur(16px);border-top:1px solid var(--line);padding:8px 6px calc(8px + env(safe-area-inset-bottom))}
  .mobilenav a{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;font-weight:700;color:var(--muted);padding:7px 4px;border-radius:10px;position:relative}
  .mobilenav a.active{color:var(--brand)}
  body[data-route='store']{padding-bottom:70px}
  body[data-route='store'] .fab-wa{bottom:92px}
  body[data-route='store'] .fab-cart{bottom:158px}
  .atop{padding:12px 16px}
  .modal .mbox{padding:24px 20px}
}

body.script:
//
/* ============================================================
   LAPTORIUM SPA — Storefront + CMS Admin + POS Kasir
   ============================================================ */
'use strict';
/* ---- KONFIGURASI: isi setelah deploy Apps Script ---- */
var CONFIG = {
  API_URL: '',              // cth: 'https://script.google.com/macros/s/AKfyc.../exec'
  API_KEY: '',              // API key dari fungsi setup() di code.gs
  WA_DEFAULT: '6281234567890'
};
/* Coba baca config tersimpan (diatur via Admin > Pengaturan) */
try {
  var _cfg = JSON.parse(localStorage.getItem('laptorium_cfg') || '{}');
  if (_cfg.API_URL) CONFIG.API_URL = _cfg.API_URL;
  if (_cfg.API_KEY) CONFIG.API_KEY = _cfg.API_KEY;
} catch (e) {}

/* ================= UTIL ================= */
function $(s, r) { return (r || document).querySelector(s); }
function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
function esc(t) { return String(t === null || t === undefined ? '' : t).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
function fmtRp(n) { n = Math.round(Number(n) || 0); return 'Rp' + n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }
function parseRp(s) { return Number(String(s || '').replace(/[^0-9]/g, '')) || 0; }
function fmtDate(s) { try { var d = new Date(String(s).replace(' ', 'T')); if (isNaN(d)) return String(s || ''); return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) + ' ' + d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }); } catch (e) { return String(s || ''); } }
function debounce(fn, ms) { var t; return function () { clearTimeout(t); var a = arguments, s = this; t = setTimeout(function () { fn.apply(s, a); }, ms); }; }
function uid(p) { return (p || 'ID') + '-' + Date.now().toString(36) + Math.floor(Math.random() * 999); }
function stars(r) { r = Math.round(Number(r) || 0); var s = ''; for (var i = 1; i <= 5; i++) s += i <= r ? '★' : '☆'; return s; }
function initials(n) { return String(n || '?').trim().split(/\s+/).slice(0, 2).map(function (w) { return w.charAt(0).toUpperCase(); }).join(''); }
function waLink(msg) {
  var wa = (SETTINGS.store_wa || CONFIG.WA_DEFAULT) + '';
  wa = wa.replace(/[^0-9]/g, '');
  if (wa.charAt(0) === '0') wa = '62' + wa.substring(1);
  return 'https://wa.me/' + wa + '?text=' + encodeURIComponent(msg || 'Halo Laptorium!');
}

/* ---- Toast ---- */
function toast(msg, type) {
  var box = $('#toasts');
  var el = document.createElement('div');
  el.className = 'toast ' + (type || '');
  var ic = type === 'success' ? 'fa-circle-check' : type === 'error' ? 'fa-circle-exclamation' : type === 'warn' ? 'fa-triangle-exclamation' : 'fa-bell';
  el.innerHTML = '<i class="fa-solid ' + ic + '"></i><span>' + esc(msg) + '</span>';
  box.appendChild(el);
  setTimeout(function () { el.classList.add('out'); setTimeout(function () { el.remove(); }, 350); }, 3200);
}

/* ---- Modal generik ---- */
function openModal(html, opts) {
  opts = opts || {};
  closeModal();
  $('#scrim').classList.add('show');
  var m = document.createElement('div');
  m.className = 'modal' + (opts.lg ? ' modal-lg' : '') + ' open';
  m.id = 'modal';
  m.innerHTML = '<div class="mbox" role="dialog" aria-modal="true"><button class="mx" data-mx="1" aria-label="Tutup"><i class="fa-solid fa-xmark"></i></button><div class="mbody">' + html + '</div></div>';
  $('#modal-root').appendChild(m);
  m.addEventListener('click', function (ev) {
    if (ev.target === m || ev.target.closest('[data-mx]')) closeModal();
  });
  var f = m.querySelector('input,select,textarea,button.btn'); if (f && !opts.noFocus) f.focus();
  return m;
}
function closeModal() {
  var m = $('#modal'); if (m) m.remove();
  if (!$('#drawer').classList.contains('open')) $('#scrim').classList.remove('show');
}
function confirmDlg(title, msg, okLabel) {
  return new Promise(function (resolve) {
    var m = openModal('<div class="center"><div style="font-size:52px;margin-bottom:10px">⚠️</div><h3 style="margin-bottom:8px">' + esc(title) + '</h3><p style="color:var(--muted);font-size:14.5px;margin-bottom:22px">' + esc(msg) + '</p><div style="display:flex;gap:10px;justify-content:center"><button class="btn btn-outline" data-no="1">Batal</button><button class="btn btn-danger" data-yes="1">' + esc(okLabel || 'Ya, lanjutkan') + '</button></div></div>', { noFocus: true });
    m.querySelector('[data-no]').onclick = function () { closeModal(); resolve(false); };
    m.querySelector('[data-yes]').onclick = function () { closeModal(); resolve(true); };
  });
}
document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { closeModal(); closeDrawer(); $('#mmenu').classList.remove('open'); } });

/* ================= API CLIENT ================= */
var Api = {
  live: false,
  async get(action, params) {
    params = params || {};
    if (!CONFIG.API_URL) throw new Error('DEMO');
    var url = CONFIG.API_URL + '?action=' + encodeURIComponent(action) + '&key=' + encodeURIComponent(CONFIG.API_KEY);
    Object.keys(params).forEach(function (k) { if (params[k] !== '' && params[k] !== null && params[k] !== undefined) url += '&' + encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
    var r = await fetch(url, { method: 'GET' });
    var j = await r.json();
    if (!j.ok) throw new Error(j.error || 'API error');
    return j.data;
  },
  async post(body) {
    if (!CONFIG.API_URL) throw new Error('DEMO');
    body.key = CONFIG.API_KEY;
    var r = await fetch(CONFIG.API_URL, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(body) });
    var j = await r.json();
    if (!j.ok) throw new Error(j.error || 'API error');
    return j.data;
  }
};
