var SETTINGS = Object.assign({}, DEMO.settings);
var DB = { categories: [], products: [], services: [], testimonials: [], banners: [], faqs: [], orders: [], customers: [], tradeins: [] };
function normBool(v) { return v === true || v === 1 || v === 'TRUE' || v === 'true' || v === '1'; }
function normProduct(r) {
  r.price = Number(r.price || 0); r.promo_price = Number(r.promo_price || 0); r.stock = Number(r.stock || 0);
  r.rating = Number(r.rating || 0); r.sold = Number(r.sold || 0);
  r.eff_price = r.promo_price > 0 ? r.promo_price : r.price;
  r.discount_pct = r.price > 0 && r.promo_price > 0 ? Math.round((1 - r.promo_price / r.price) * 100) : 0;
  if (typeof r.images === 'string') {
    var s = r.images.trim();
    if (s.charAt(0) === '[') { try { r.images = JSON.parse(s); } catch (e) { r.images = []; } }
    else if (s) r.images = s.split(',').map(function (x) { return x.trim(); });
    else r.images = [];
  }
  if (!Array.isArray(r.images)) r.images = [];
  if (r.image_url && r.images.indexOf(r.image_url) === -1) r.images.unshift(r.image_url);
  r.featured = normBool(r.featured); r.bestseller = normBool(r.bestseller); r.is_new = normBool(r.is_new);
  return r;
}
var Store = {
  async init() {
    if (!CONFIG.API_URL) { this.loadDemo(); return; }
    try {
      var s = await Api.get('getSettingsPublic');
      SETTINGS = Object.assign({}, DEMO.settings, s);
      Api.live = true;
    } catch (e) { this.loadDemo(); return; }
    try {
      var res = await Promise.all([
        Api.get('getCategories').catch(function () { return DEMO.categories; }),
        Api.get('getProducts', { limit: 100 }).catch(function () { return { items: DEMO.products }; }),
        Api.get('getServices').catch(function () { return DEMO.services; }),
        Api.get('getTestimonials').catch(function () { return DEMO.testimonials; }),
        Api.get('getBanners').catch(function () { return DEMO.banners; }),
        Api.get('getFaqs').catch(function () { return DEMO.faqs; })
      ]);
      DB.categories = res[0] || [];
      var pr = res[1]; DB.products = ((pr && pr.items) || []).map(normProduct);
      DB.services = res[2] || []; DB.testimonials = res[3] || []; DB.banners = res[4] || []; DB.faqs = res[5] || [];
    } catch (e) { this.loadDemo(); }
  },
  loadDemo() {
    Api.live = false;
    DB.categories = DEMO.categories; DB.products = DEMO.products.map(normProduct);
    DB.services = DEMO.services; DB.testimonials = DEMO.testimonials;
    DB.banners = DEMO.banners; DB.faqs = DEMO.faqs;
    DB.orders = DEMO.orders; DB.customers = DEMO.customers; DB.tradeins = DEMO.tradeins;
  }
};
