  var w = $('#api-warn');
  if (w) {
    if (!Api.live) { w.style.display = 'block'; w.innerHTML = 'Mode <b>DEMO</b> — hubungkan Web App URL + API key di <b>Pengaturan</b> agar data tersimpan ke Spreadsheet. Login demo: <b>admin / admin123</b>'; }
    else w.style.display = 'none';
  }
}

/* ================= ROUTER ================= */
var ROUTE = 'store', APAGE = 'dashboard';
function router() {
  var h = location.hash || '#top';
  $('#mmenu').classList.remove('open');
  if (h.indexOf('#/admin') === 0) {
    ROUTE = 'admin';
    APAGE = h.split('/')[2] || 'dashboard';
    document.body.dataset.route = 'admin';
    Admin.enter();
    window.scrollTo(0, 0);
    return;
  }
  if (h.indexOf('#/pos') === 0) {
    ROUTE = 'pos'; document.body.dataset.route = 'pos';
    POS.enter(); window.scrollTo(0, 0); return;
  }
  if (h.indexOf('#/lacak') === 0) {
    ROUTE = 'lacak'; document.body.dataset.route = 'lacak';
    window.scrollTo(0, 0); observeRv(); return;
  }
  ROUTE = 'store'; document.body.dataset.route = 'store';
  if (h.length > 1) {
    var t = document.querySelector(h);
    if (t) setTimeout(function () { t.scrollIntoView({ behavior: 'smooth' }); }, 60);
  } else window.scrollTo(0, 0);
  observeRv();
}
window.addEventListener('hashchange', router);

/* ================= ANIMASI: reveal + counter ================= */
var io = null;
function observeRv() {
  var els = $$('.rv,.rv-l,.rv-r').filter(function (el) { return !el.classList.contains('in'); });
  if (!('IntersectionObserver' in window)) { els.forEach(function (el) { el.classList.add('in'); }); return; }
  if (!io) io = new IntersectionObserver(function (es) {
    es.forEach(function (en) {
      if (en.isIntersecting) {
        var el = en.target;
        var sibs = Array.prototype.slice.call(el.parentNode.children).filter(function (c) { return c.classList && (c.classList.contains('rv') || c.classList.contains('rv-l') || c.classList.contains('rv-r')); });
        var idx = sibs.indexOf(el);
        el.style.transitionDelay = Math.min(idx * 90, 540) + 'ms';
        el.classList.add('in'); io.unobserve(el);
      }
    });
  }, { threshold: 0.12 });
  els.forEach(function (el) { io.observe(el); });
  // counters
  var cs = $$('.count').filter(function (el) { return !el.dataset.done; });
  var cio = new IntersectionObserver(function (es) {
    es.forEach(function (en) {
      if (!en.isIntersecting) return;
      var el = en.target; el.dataset.done = '1'; cio.unobserve(el);
      var to = parseFloat(el.dataset.to), dec = parseInt(el.dataset.dec || '0', 10);
      var st = null;
      var step = function (ts) {
        if (!st) st = ts;
        var p = Math.min((ts - st) / 1400, 1), e = 1 - Math.pow(1 - p, 3);
        el.textContent = (to * e).toFixed(dec);
        if (p < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });
  }, { threshold: 0.5 });
  cs.forEach(function (el) { cio.observe(el); });
}

/* ================= STOREFRONT ================= */
var F = { cat: '', q: '', cond: '', sort: 'newest', page: 1, limit: 12 };
function effP(p) { return p.promo_price > 0 ? p.promo_price : p.price; }
function stockBadge(p) {
  if (p.stock <= 0) return '<span class="pstock out">Stok habis</span>';
  if (p.stock <= 3) return '<span class="pstock low">Sisa ' + p.stock + '</span>';
  return '<span class="pstock ok">Stok tersedia</span>';
}
function filteredProducts() {
  var list = DB.products.filter(function (p) { return (p.status || 'active') === 'active'; });
  if (F.cat) list = list.filter(function (p) { return p.category === F.cat; });
  if (F.cond) list = list.filter(function (p) { return p.condition === F.cond; });
  if (F.q) { var q = F.q.toLowerCase(); list = list.filter(function (p) { return (p.name + ' ' + p.brand + ' ' + p.category + ' ' + (p.specs || '')).toLowerCase().indexOf(q) !== -1; }); }
  if (F.sort === 'price_asc') list.sort(function (a, b) { return effP(a) - effP(b); });
  else if (F.sort === 'price_desc') list.sort(function (a, b) { return effP(b) - effP(a); });
  else if (F.sort === 'popular') list.sort(function (a, b) { return (b.sold || 0) - (a.sold || 0); });
  else if (F.sort === 'name') list.sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });
  return list;
}
function renderCats() {
  var box = $('#cat-pills');
  var html = '<button class="pill' + (F.cat === '' ? ' active' : '') + '" data-cat="">Semua</button>';
  DB.categories.forEach(function (c) {
    html += '<button class="pill' + (F.cat === c.name ? ' active' : '') + '" data-cat="' + esc(c.name) + '">' + esc(c.icon || '📦') + ' ' + esc(c.name) + '</button>';
  });
  box.innerHTML = html;
  $$('#cat-pills .pill').forEach(function (b) {
    b.onclick = function () { F.cat = b.dataset.cat; F.page = 1; renderCats(); renderProducts(); };
  });
}
function pcardHTML(p, i) {
  var loved = Wishlist.has(p.id) ? ' loved' : '';
  var heart = Wishlist.has(p.id) ? 'fa-solid' : 'fa-regular';
  return '<article class="pcard rv" style="transition-delay:' + Math.min(i * 70, 420) + 'ms">' +
    '<div class="pcard-img"><img loading="lazy" src="' + esc(p.images[0] || '') + '" alt="' + esc(p.name) + '" data-qv="' + esc(p.id) + '" style="cursor:pointer"/>' +
    (p.badge ? '<span class="pbadge' + (p.condition === 'second' ? ' second' : '') + '">' + esc(p.badge) + '</span>' : '') +
    '<button class="pwish' + loved + '" data-wish="' + esc(p.id) + '" aria-label="Wishlist"><i class="' + heart + ' fa-heart"></i></button>' +
    stockBadge(p) + '</div>' +
    '<div class="pcard-body"><span class="pcat">' + esc(p.category) + '</span>' +
    '<h3 class="pname" data-qv="' + esc(p.id) + '" style="cursor:pointer">' + esc(p.name) + '</h3>' +
    '<p class="pspec">' + esc(p.specs || '') + '</p>' +
    '<div class="prate"><span class="stars">' + stars(p.rating) + '</span><span>' + Number(p.rating || 0).toFixed(1) + ' • Terjual ' + (p.sold || 0) + '</span></div>' +
    '<div class="pprice"><span class="now">' + fmtRp(effP(p)) + '</span>' +
    (p.promo_price > 0 ? '<span class="was">' + fmtRp(p.price) + '</span><span class="pdisc">-' + p.discount_pct + '%</span>' : '') + '</div>' +
    '<div class="pcard-actions"><button class="btn btn-outline" data-qv="' + esc(p.id) + '">Detail</button>' +
    '<button class="btn btn-primary" data-add="' + esc(p.id) + '"' + (p.stock <= 0 ? ' disabled' : '') + '><i class="fa-solid fa-cart-plus"></i> Keranjang</button></div>' +
    '</div></article>';
}
function renderProducts(append) {
  var list = filteredProducts();
  var grid = $('#pgrid');
  var slice = list.slice(0, F.page * F.limit);
  if (!list.length) {
    grid.innerHTML = '<div class="empty" style="grid-column:1/-1"><i class="fa-solid fa-box-open"></i><h3>Produk tidak ditemukan</h3><p>Coba kata kunci atau kategori lain.</p></div>';
  } else {
    grid.innerHTML = slice.map(pcardHTML).join('');
  }
  $('#btn-more').style.display = list.length > slice.length ? '' : 'none';
  $('#stock-info').innerHTML = list.length + ' produk • update ' + new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'short' });
  $$('#pgrid [data-add]').forEach(function (b) { b.onclick = function () { Cart.add(b.dataset.add, 1); }; });
  $$('#pgrid [data-qv]').forEach(function (b) { b.onclick = function () { QuickView.open(b.dataset.qv); }; });
  $$('#pgrid [data-wish]').forEach(function (b) { b.onclick = function (ev) { ev.stopPropagation(); Wishlist.toggle(b.dataset.wish); renderProducts(); }; });
  observeRv();
}
/* ---- Promo slider ---- */
var promoIdx = 0, promoTimer = null;
function renderPromo() {
  var box = $('#promo-slider');
  if (!DB.banners.length) { box.style.display = 'none'; return; }
  box.style.display = '';
  box.innerHTML = DB.banners.map(function (b, i) {
    return '<div class="pslide' + (i === 0 ? ' active' : '') + '"><img class="bg" src="' + esc(b.image_url) + '" alt="' + esc(b.title) + '" loading="lazy"/><div class="overlay"></div><div class="txt"><h3>' + esc(b.title) + '</h3><p>' + esc(b.subtitle || '') + '</p><a class="btn btn-white" href="' + esc(b.cta_link || '#katalog') + '">' + esc(b.cta_text || 'Lihat') + ' <i class="fa-solid fa-arrow-right"></i></a></div></div>';
  }).join('') + '<div class="pdots">' + DB.banners.map(function (_, i) { return '<button data-dot="' + i + '" aria-label="Banner ' + (i + 1) + '" class="' + (i === 0 ? 'active' : '') + '"></button>'; }).join('') + '</div>';
  $$('#promo-slider [data-dot]').forEach(function (d) { d.onclick = function () { promoGo(parseInt(d.dataset.dot, 10)); }; });
  clearInterval(promoTimer);
  promoTimer = setInterval(function () { promoGo((promoIdx + 1) % DB.banners.length); }, 6000);
}
function promoGo(i) {
  promoIdx = i;
  $$('#promo-slider .pslide').forEach(function (s, k) { s.classList.toggle('active', k === i); });
  $$('#promo-slider [data-dot]').forEach(function (d, k) { d.classList.toggle('active', k === i); });
}
/* ---- Layanan / testimoni / FAQ ---- */
function renderServices() {
  $('#svc-grid').innerHTML = DB.services.map(function (s, i) {
    var feats = String(s.features || '').split('|').filter(Boolean).map(function (f) { return '<li><i class="fa-solid fa-check"></i>' + esc(f) + '</li>'; }).join('');
    return '<div class="svc rv" style="transition-delay:' + Math.min(i * 80, 400) + 'ms"><div class="svc-ic">' + esc(s.icon || '⚙️') + '</div><h3>' + esc(s.name) + '</h3><p>' + esc(s.short_desc || s.description || '') + '</p><ul>' + feats + '</ul><span class="price">Mulai dari ' + esc(s.price_from || '-') + '</span><br/><a class="btn btn-outline-w btn-sm" style="margin-top:14px" target="_blank" rel="noopener" href="' + waLink('Halo ' + SETTINGS.store_name + '! Saya mau tanya layanan: ' + s.name) + '"><i class="fa-brands fa-whatsapp"></i> Tanya Layanan Ini</a></div>';
  }).join('');
  observeRv();
}
function renderTestimonials() {
  var list = DB.testimonials.slice(0, 6);
  $('#tst-track').innerHTML = list.map(function (t, i) {
    return '<div class="tst rv" style="transition-delay:' + Math.min(i * 80, 400) + 'ms"><div class="stars">' + stars(t.rating) + '</div><p>"' + esc(t.text) + '"</p><div class="tst-who"><span class="avatar">' + esc(initials(t.name)) + '</span><span><b>' + esc(t.name) + '</b><span>' + esc(t.role || '') + '</span></span></div></div>';
  }).join('');
  observeRv();
}
function renderFaqs() {
  $('#faq-list').innerHTML = DB.faqs.map(function (f) {
    return '<div class="faq rv"><button class="faq-q" aria-expanded="false">' + esc(f.question) + '<span class="fx"><i class="fa-solid fa-plus"></i></span></button><div class="faq-a"><div>' + esc(f.answer) + '</div></div></div>';
  }).join('');
  $$('#faq-list .faq-q').forEach(function (q) {
    q.onclick = function () {
      var item = q.parentNode, open = item.classList.contains('open');
      $$('#faq-list .faq').forEach(function (x) { x.classList.remove('open'); x.querySelector('.faq-a').style.maxHeight = null; x.querySelector('.faq-q').setAttribute('aria-expanded', 'false'); });
      if (!open) { item.classList.add('open'); var a = item.querySelector('.faq-a'); a.style.maxHeight = a.scrollHeight + 'px'; q.setAttribute('aria-expanded', 'true'); }
    };
  });
  observeRv();
}
function renderStorefront() { renderCats(); renderProducts(); renderPromo(); renderServices(); renderTestimonials(); renderFaqs(); }

/* ================= QUICK VIEW ================= */
