    if (!p) return;
    var imgs = p.images.length ? p.images : [p.image_url];
    var m = openModal(
      '<div class="qv-grid"><div><img class="main" id="qv-img" src="' + esc(imgs[0]) + '" alt="' + esc(p.name) + '"/>' +
      (imgs.length > 1 ? '<div class="qv-thumbs">' + imgs.map(function (im, i) { return '<img src="' + esc(im) + '" data-th="' + i + '" class="' + (i === 0 ? 'sel' : '') + '" alt="Foto ' + (i + 1) + '"/>'; }).join('') + '</div>' : '') + '</div>' +
      '<div><span class="pcat">' + esc(p.category) + ' • ' + (p.condition === 'second' ? 'Second' : 'Baru') + '</span>' +
      '<h2 style="font-size:23px;margin:6px 0">' + esc(p.name) + '</h2>' +
      '<div class="prate"><span class="stars">' + stars(p.rating) + '</span><span>' + Number(p.rating || 0).toFixed(1) + ' • Terjual ' + (p.sold || 0) + ' • SKU ' + esc(p.sku || '-') + '</span></div>' +
      '<div class="pprice" style="margin:10px 0"><span class="now" style="font-size:26px">' + fmtRp(effP(p)) + '</span>' +
      (p.promo_price > 0 ? '<span class="was">' + fmtRp(p.price) + '</span><span class="pdisc">-' + p.discount_pct + '%</span>' : '') + '</div>' +
      '<p style="font-size:14px;color:var(--muted)"><b style="color:var(--ink)">Spesifikasi:</b> ' + esc(p.specs || '-') + '</p>' +
      '<p style="font-size:14px;color:var(--muted);margin-top:6px">' + esc(p.description || '') + '</p>' +
      '<div style="margin:12px 0">' + stockBadge(p) + '</div>' +
      '<div style="display:flex;gap:10px;align-items:center;margin-bottom:14px"><span class="qty"><button data-qvmin="1">−</button><span id="qv-qty">1</span><button data-qvplus="1">+</button></span>' +
      '<button class="btn btn-primary" style="flex:1" id="qv-add"' + (p.stock <= 0 ? ' disabled' : '') + '><i class="fa-solid fa-cart-plus"></i> + Keranjang</button></div>' +
      '<a class="btn btn-success btn-block" target="_blank" rel="noopener" href="' + waLink('Halo ' + SETTINGS.store_name + '! Saya mau beli: ' + p.name + ' (' + fmtRp(effP(p)) + '). Apakah masih tersedia?') + '"><i class="fa-brands fa-whatsapp"></i> Beli via WhatsApp</a>' +
      '</div></div>', { lg: true });
    var q = 1, max = Math.max(p.stock, 1);
    $$('[data-th]', m).forEach(function (t) {
      t.onclick = function () { $('#qv-img', m).src = imgs[parseInt(t.dataset.th, 10)]; $$('[data-th]', m).forEach(function (x) { x.classList.remove('sel'); }); t.classList.add('sel'); };
    });
    $('[data-qvmin]', m).onclick = function () { q = Math.max(1, q - 1); $('#qv-qty', m).textContent = q; };
    $('[data-qvplus]', m).onclick = function () { q = Math.min(max, q + 1); $('#qv-qty', m).textContent = q; };
    $('#qv-add', m).onclick = function () { Cart.add(p.id, q); closeModal(); };
  }
};

/* ================= WISHLIST ================= */
var Wishlist = {
  items: JSON.parse(localStorage.getItem('laptorium_wish') || '[]'),
  save() { localStorage.setItem('laptorium_wish', JSON.stringify(this.items)); this.badge(); },
  has(id) { return this.items.indexOf(String(id)) !== -1; },
  toggle(id) {
    id = String(id);
    if (this.has(id)) { this.items = this.items.filter(function (x) { return x !== id; }); toast('Dihapus dari wishlist'); }
    else { this.items.push(id); toast('Ditambahkan ke wishlist', 'success'); }
    this.save();
  },
  badge() {
    var b = $('#wish-count');
    b.style.display = this.items.length ? '' : 'none';
    b.textContent = this.items.length;
  },
  open() {
    var list = this.items.map(function (id) { return DB.products.find(function (p) { return String(p.id) === String(id); }); }).filter(Boolean);
    openModal('<h3 style="margin-bottom:4px"><i class="fa-solid fa-heart" style="color:#e11d48"></i> Wishlist Kamu</h3><p style="color:var(--muted);font-size:14px;margin-bottom:16px">' + list.length + ' produk disimpan</p>' +
      (list.length ? list.map(function (p) {
        return '<div class="citem"><img src="' + esc(p.images[0] || '') + '" alt=""/><div class="ci"><b>' + esc(p.name) + '</b><div class="cp">' + fmtRp(effP(p)) + '</div><button class="btn btn-primary btn-sm" data-wadd="' + esc(p.id) + '">+ Keranjang</button></div><button class="rm" data-wrm="' + esc(p.id) + '"><i class="fa-solid fa-trash"></i></button></div>';
      }).join('') : '<div class="empty"><i class="fa-regular fa-heart"></i><p>Belum ada wishlist. Ketuk ikon ♥ di produk favoritmu.</p></div>'));
    $$('#modal [data-wadd]').forEach(function (b) { b.onclick = function () { Cart.add(b.dataset.wadd, 1); }; });
    $$('#modal [data-wrm]').forEach(function (b) { b.onclick = function () { Wishlist.toggle(b.dataset.wrm); Wishlist.open(); renderProducts(); }; });
  }
};

/* ================= CART + CHECKOUT ================= */
var Cart = {
  items: JSON.parse(localStorage.getItem('laptorium_cart') || '[]'), // [{id, qty}]
  save() { localStorage.setItem('laptorium_cart', JSON.stringify(this.items)); this.badge(); renderDrawer(); },
  badge() {
    var n = this.items.reduce(function (s, it) { return s + it.qty; }, 0);
    var b = $('#cart-count'); b.textContent = n;
    b.classList.remove('pop'); void b.offsetWidth; b.classList.add('pop');
  },
  lines() {
    var self = this;
    return this.items.map(function (it) {
      var p = DB.products.find(function (x) { return String(x.id) === String(it.id); });
      return p ? { p: p, qty: it.qty } : null;
    }).filter(Boolean);
  },
  add(id, qty) {
    qty = qty || 1;
    var p = DB.products.find(function (x) { return String(x.id) === String(id); });
    if (!p) return;
    if (p.stock <= 0) { toast('Stok habis', 'error'); return; }
    var ex = this.items.find(function (it) { return String(it.id) === String(id); });
    var cur = ex ? ex.qty : 0;
    if (cur + qty > p.stock) { toast('Stok hanya tersisa ' + p.stock, 'warn'); qty = p.stock - cur; if (qty <= 0) return; }
    if (ex) ex.qty += qty; else this.items.push({ id: String(id), qty: qty });
    this.save();
    toast(p.name + ' masuk keranjang', 'success');
    openDrawer();
  },
  setQty(id, qty) {
    var p = DB.products.find(function (x) { return String(x.id) === String(id); });
    qty = Math.max(0, Math.min(qty, p ? p.stock : 99));
    this.items = this.items.map(function (it) { return String(it.id) === String(id) ? { id: it.id, qty: qty } : it; }).filter(function (it) { return it.qty > 0; });
    this.save();
  },
  remove(id) { this.items = this.items.filter(function (it) { return String(it.id) !== String(id); }); this.save(); },
  clear() { this.items = []; this.save(); },
  subtotal() { return this.lines().reduce(function (s, l) { return s + effP(l.p) * l.qty; }, 0); }
};
function openDrawer() { renderDrawer(); $('#drawer').classList.add('open'); $('#scrim').classList.add('show'); }
function closeDrawer() { $('#drawer').classList.remove('open'); if (!$('#modal')) $('#scrim').classList.remove('show'); }
function renderDrawer() {
  var lines = Cart.lines();
  var box = $('#drawer-items'), foot = $('#drawer-foot');
  $('#drawer-n').textContent = lines.length ? '(' + lines.reduce(function (s, l) { return s + l.qty; }, 0) + ' item)' : '';
  if (!lines.length) {
    box.innerHTML = '<div class="empty"><i class="fa-solid fa-cart-shopping"></i><h3>Keranjang kosong</h3><p>Yuk, cari laptop / PC impianmu.</p><a class="btn btn-primary btn-sm" style="margin-top:12px" href="#katalog" id="empty-shop">Lihat Katalog</a></div>';
    foot.innerHTML = '';
    var es = $('#empty-shop'); if (es) es.onclick = closeDrawer;
    return;
  }
  box.innerHTML = lines.map(function (l) {
    return '<div class="citem"><img src="' + esc(l.p.images[0] || '') + '" alt=""/><div class="ci"><b>' + esc(l.p.name) + '</b><div class="cp">' + fmtRp(effP(l.p)) + '</div><span class="qty"><button data-dec="' + esc(l.p.id) + '">−</button><span>' + l.qty + '</span><button data-inc="' + esc(l.p.id) + '">+</button></span></div><button class="rm" data-rm="' + esc(l.p.id) + '" aria-label="Hapus"><i class="fa-solid fa-trash"></i></button></div>';
  }).join('');
  var sub = Cart.subtotal();
  var freeMin = Number(SETTINGS.free_shipping_min || 5000000);
  var ship = Number(SETTINGS.shipping_flat || 15000);
  var isFree = sub >= freeMin;
  foot.innerHTML = '<div class="trow"><span>Subtotal</span><b style="color:var(--ink)">' + fmtRp(sub) + '</b></div>' +
    '<div class="trow"><span>Ongkir ' + (isFree ? '(GRATIS 🎉)' : '') + '</span><b style="color:var(--ink)">' + (isFree ? 'Rp0' : fmtRp(ship)) + '</b></div>' +
    (!isFree ? '<div style="font-size:12.5px;color:var(--muted);margin:4px 0">Belanja <b>' + fmtRp(freeMin - sub) + '</b> lagi untuk gratis ongkir!</div>' : '') +
    '<div class="trow grand"><span>Total</span><span>' + fmtRp(sub + (isFree ? 0 : ship)) + '</span></div>' +
    '<button class="btn btn-primary btn-block" id="btn-checkout" style="margin-top:12px"><i class="fa-solid fa-lock"></i> Checkout Sekarang</button>' +
    '<button class="btn btn-ghost btn-block btn-sm" id="btn-continue">+ Lanjut belanja</button>';
  $$('#drawer-items [data-inc]').forEach(function (b) { b.onclick = function () { var l = Cart.lines().find(function (x) { return String(x.p.id) === b.dataset.inc; }); Cart.setQty(b.dataset.inc, (l ? l.qty : 0) + 1); }; });
  $$('#drawer-items [data-dec]').forEach(function (b) { b.onclick = function () { var l = Cart.lines().find(function (x) { return String(x.p.id) === b.dataset.dec; }); Cart.setQty(b.dataset.dec, (l ? l.qty : 1) - 1); }; });
  $$('#drawer-items [data-rm]').forEach(function (b) { b.onclick = function () { Cart.remove(b.dataset.rm); }; });
  $('#btn-checkout').onclick = Checkout.open;
  $('#btn-continue').onclick = closeDrawer;
}
var Checkout = {
  pay: 'transfer',
  open() {
    if (!Cart.lines().length) { toast('Keranjang masih kosong', 'warn'); return; }
    closeDrawer();
    var sub = Cart.subtotal();
    var freeMin = Number(SETTINGS.free_shipping_min || 5000000);
    var ship = sub >= freeMin ? 0 : Number(SETTINGS.shipping_flat || 15000);
    var m = openModal('<h3 style="margin-bottom:4px">🔒 Checkout Pesanan</h3><p style="color:var(--muted);font-size:14px;margin-bottom:16px">Isi data pengiriman, kami proses <b>hari ini juga</b>.</p>' +
      '<div class="field"><label>Nama lengkap *</label><input id="co-name" placeholder="Nama penerima"/></div>' +
      '<div class="frow"><div class="field"><label>No. WhatsApp *</label><input id="co-wa" inputmode="tel" placeholder="08…"/></div>' +
      '<div class="field"><label>Email (opsional)</label><input id="co-email" type="email" placeholder="nama@email.com"/></div></div>' +
      '<div class="field"><label>Alamat lengkap *</label><textarea id="co-addr" style="min-height:64px" placeholder="Jalan, no. rumah, patokan, kota, kode pos"></textarea></div>' +
      '<div class="field"><label>Catatan (opsional)</label><input id="co-note" placeholder="cth: minta instal Office + antivirus"/></div>' +
      '<div class="field"><label>Metode pembayaran</label><div class="pay-opts" id="co-pay">' +
      '<button data-p="transfer"><i class="fa-solid fa-building-columns"></i>Transfer</button>' +
      '<button data-p="qris"><i class="fa-solid fa-qrcode"></i>QRIS</button>' +
      '<button data-p="cod"><i class="fa-solid fa-money-bill-wave"></i>COD</button>' +
      '<button data-p="cicilan"><i class="fa-solid fa-credit-card"></i>Cicilan</button>' +
      '<button data-p="toko"><i class="fa-solid fa-store"></i>Ambil di Toko</button>' +
      '</div></div>' +
      '<div class="trow"><span>Subtotal</span><b style="color:var(--ink)">' + fmtRp(sub) + '</b></div>' +
      '<div class="trow"><span>Ongkir</span><b style="color:var(--ink)">' + (ship ? fmtRp(ship) : 'GRATIS') + '</b></div>' +
      '<div class="trow grand"><span>Total Bayar</span><span>' + fmtRp(sub + ship) + '</span></div>' +
      '<button class="btn btn-primary btn-block" id="co-submit" style="margin-top:14px"><i class="fa-solid fa-check"></i> Buat Pesanan • ' + fmtRp(sub + ship) + '</button>');
    Checkout.pay = 'transfer';
    var paint = function () { $$('#co-pay button', m).forEach(function (b) { b.classList.toggle('sel', b.dataset.p === Checkout.pay); }); };
    paint();
    $$('#co-pay button', m).forEach(function (b) { b.onclick = function () { Checkout.pay = b.dataset.p; paint(); }; });
    $('#co-submit', m).onclick = function () { Checkout.submit(sub, ship); };
  },
  async submit(sub, ship) {
    var name = $('#co-name').value.trim(), wa = $('#co-wa').value.trim(), addr = $('#co-addr').value.trim();
    if (!name || !wa || !addr) { toast('Lengkapi nama, WhatsApp, dan alamat', 'error'); return; }
    var btn = $('#co-submit'); btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Memproses…';
    var payload = {
      action: 'createOrder', customer_name: name, customer_wa: wa,
      customer_email: $('#co-email').value.trim(), customer_address: addr, notes: $('#co-note').value.trim(),
      payment_method: Checkout.pay, shipping: ship,
      items: Cart.lines().map(function (l) { return { id: l.p.id, qty: l.qty }; })
    };
    try {
      var order;
      if (Api.live) {
        order = await Api.post(payload);
        // refresh stok produk
        try { var pr = await Api.get('getProducts', { limit: 100 }); DB.products = (pr.items || []).map(normProduct); renderProducts(); } catch (e) {}
      } else {
        order = {
          id: uid('ORD'), invoice: 'INV-20261007-' + Math.floor(1000 + Math.random() * 9000),
          date: new Date().toISOString(), customer_name: name, total: sub + ship,
          payment_method: Checkout.pay, items: Cart.lines().map(function (l) { return { name: l.p.name, qty: l.qty, price: effP(l.p), subtotal: effP(l.p) * l.qty }; })
        };
        // potong stok demo
        Cart.lines().forEach(function (l) { l.p.stock = Math.max(0, l.p.stock - l.qty); l.p.sold = (l.p.sold || 0) + l.qty; });
        renderProducts();
      }
      Cart.clear();
      var msg = 'Halo ' + SETTINGS.store_name + '! Saya baru order ' + order.invoice + ' (' + fmtRp(order.total) + '). Mohon info pembayaran. Terima kasih 🙏';
      openModal('<div class="center"><div style="font-size:64px">🎉</div><h3>Pesanan Berhasil Dibuat!</h3><p style="color:var(--muted);margin:8px 0 4px">Nomor invoice:</p><div style="font-size:22px;font-weight:800;color:var(--brand-dark);background:#eff6ff;border-radius:12px;padding:10px;margin-bottom:12px">' + esc(order.invoice) + '</div><p style="font-size:14px;color:var(--muted)">Total <b style="color:var(--ink)">' + fmtRp(order.total) + '</b> • ' + esc(order.payment_method).toUpperCase() + '<br/>Simpan nomor invoice untuk melacak pesanan.</p><div style="display:flex;gap:10px;margin-top:18px;flex-wrap:wrap"><a class="btn btn-success" style="flex:1" target="_blank" rel="noopener" href="' + waLink(msg) + '"><i class="fa-brands fa-whatsapp"></i> Konfirmasi WA</a><a class="btn btn-outline" style="flex:1" href="#/lacak">Lacak Pesanan</a></div></div>');
    } catch (err) {
      toast(err.message || 'Gagal membuat pesanan', 'error');
      btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-check"></i> Buat Pesanan';
    }
  }
};

