/* ================= LACAK PESANAN ================= */
var STEP_ORDER = ['pending', 'paid', 'process', 'shipped', 'completed'];
var STEP_LABEL = { pending: ['Pesanan diterima', 'Menunggu pembayaran/konfirmasi'], paid: ['Pembayaran diterima', 'Pesanan disiapkan'], process: ['Diproses', 'Unit dicek & dibungkus'], shipped: ['Dikirim', 'Dalam perjalanan ke alamatmu'], completed: ['Selesai', 'Pesanan tiba. Terima kasih!'] };
async function trackOrder(ev) {
  ev.preventDefault();
  var code = $('#track-code').value.trim();
  if (!code) { toast('Masukkan nomor invoice dulu', 'warn'); return; }
  var box = $('#track-result');
  box.innerHTML = '<div class="sk" style="height:180px;margin-top:16px"></div>';
  var o = null;
  try {
    if (Api.live) o = await Api.get('trackOrder', { code: code });
    else {
      var f = DEMO.orders.find(function (x) { return x.invoice.toLowerCase() === code.toLowerCase(); });
      if (f) { o = Object.assign({}, f); try { o.items = JSON.parse(f.items_json); } catch (e) { o.items = []; } }
    }
  } catch (e) {}
  if (!o) {
    box.innerHTML = '<div class="empty"><i class="fa-solid fa-face-frown"></i><h3>Invoice tidak ditemukan</h3><p>Periksa kembali nomor invoicemu atau hubungi admin.</p><a class="btn btn-success btn-sm" style="margin-top:10px" target="_blank" rel="noopener" href="' + waLink('Halo, saya mau menanyakan status pesanan. Invoice: ' + code) + '"><i class="fa-brands fa-whatsapp"></i> Tanya Admin</a></div>';
    return;
  }
  var items = o.items || [];
  try { if (!items.length && o.items_json) items = JSON.parse(o.items_json); } catch (e) {}
  var st = o.order_status === 'cancelled' ? -1 : (o.payment_status === 'paid' && o.order_status === 'pending' ? 1 : STEP_ORDER.indexOf(o.order_status));
  if (st < 0 && o.order_status !== 'cancelled') st = 0;
  var tl = STEP_ORDER.map(function (k, i) {
    var done = o.order_status !== 'cancelled' && i <= st;
    return '<div class="tstep' + (done ? ' done' : '') + '"><span class="dot"><i class="fa-solid ' + (done ? 'fa-check' : 'fa-circle') + '"></i></span><span><b>' + STEP_LABEL[k][0] + '</b><span style="color:var(--muted);font-size:13.5px">' + STEP_LABEL[k][1] + '</span></span></div>';
  }).join('');
  box.innerHTML = '<div style="margin-top:18px;background:#f8faff;border:1px solid var(--line);border-radius:16px;padding:20px">' +
    '<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:12px"><div><b style="font-size:17px">' + esc(o.invoice) + '</b><br/><span style="font-size:13px;color:var(--muted)">' + fmtDate(o.date || o.created_at) + ' • ' + esc(o.customer_name || '') + '</span></div>' +
    '<div style="text-align:right"><span class="badge ' + (o.payment_status === 'paid' ? 'b-green' : 'b-amber') + '">' + (o.payment_status === 'paid' ? 'Lunas' : 'Belum bayar') + '</span> <span class="badge b-blue">' + esc(statusOrder(o.order_status)) + '</span></div></div>' +
    items.map(function (it) { return '<div class="trow"><span>' + esc(it.name) + ' ×' + it.qty + '</span><b style="color:var(--ink)">' + fmtRp(it.subtotal || it.price * it.qty) + '</b></div>'; }).join('') +
    '<div class="trow grand"><span>Total</span><span>' + fmtRp(o.total) + '</span></div></div>' +
    (o.order_status === 'cancelled' ? '<div class="empty"><i class="fa-solid fa-ban"></i><h3>Pesanan dibatalkan</h3><p>Hubungi admin jika ini kesalahan.</p></div>' : '<div class="timeline">' + tl + '</div>');
}
function statusOrder(s) {
  return { pending: 'Menunggu', paid: 'Dibayar', process: 'Diproses', shipped: 'Dikirim', completed: 'Selesai', cancelled: 'Dibatalkan' }[s] || s;
}

