    $$('#apages .apage').forEach(function (d) { d.classList.remove('active'); });
    var el = $('#ap-' + page); if (el) el.classList.add('active');
    var titles = { dashboard: 'Dashboard', orders: 'Pesanan', tradein: 'Trade-In Masuk', customers: 'Pelanggan', reports: 'Laporan Penjualan', products: 'Produk', categories: 'Kategori', services: 'Layanan', testimonials: 'Testimoni', banners: 'Banner Promo', faqs: 'FAQ', settings: 'Pengaturan', logs: 'Log Aktivitas' };
    $('#apage-title').textContent = titles[page] || 'Dashboard';
    $('#aside').classList.remove('open');
    var fn = { dashboard: pDashboard, orders: pOrders, tradein: pTradein, customers: pCustomers, reports: pReports, products: pProducts, categories: pCategories, services: pServices, testimonials: pTestimonials, banners: pBanners, faqs: pFaqs, settings: pSettings, logs: pLogs }[page];
    if (fn) fn();
  },
  async refreshBadges() {
    try {
      var dash = await adminDash();
      var bo = $('#bdg-orders'), bt = $('#bdg-trade');
      if (dash.pending_orders > 0) { bo.style.display = ''; bo.textContent = dash.pending_orders; } else bo.style.display = 'none';
      if (dash.pending_tradeins > 0) { bt.style.display = ''; bt.textContent = dash.pending_tradeins; } else bt.style.display = 'none';
    } catch (e) {}
  }
};
/* ---- helper data admin (live/demo) ---- */
async function adminDash() {
  if (Api.live) return Api.get('getDashboard', {});
  var orders = DB.orders.length ? DB.orders : DEMO.orders;
  var paid = orders.filter(function (o) { return o.payment_status === 'paid'; });
  var rev = paid.reduce(function (s, o) { return s + Number(o.total || 0); }, 0);
  var map = {}, days = [];
  for (var i = 6; i >= 0; i--) { var d = new Date(Date.now() - i * 864e5).toISOString().slice(0, 10); days.push(d); map[d] = 0; }
  paid.forEach(function (o) { var k = String(o.date).slice(0, 10); if (map[k] !== undefined) map[k] += Number(o.total || 0); });
  return {
    revenue: rev, orders_count: orders.length, products_count: DB.products.length, customers_count: DB.customers.length,
    pending_orders: orders.filter(function (o) { return o.order_status === 'pending'; }).length,
    pending_tradeins: DB.tradeins.filter(function (t) { return t.status === 'pending'; }).length,
    today_revenue: Math.round(rev / 14), today_orders: 2,
    chart7: days.map(function (d) { return { date: d, total: map[d] }; }),
    top_products: DB.products.slice().sort(function (a, b) { return b.sold - a.sold; }).slice(0, 5).map(function (p) { return { name: p.name, sold: p.sold, stock: p.stock }; }),
    low_stock: DB.products.filter(function (p) { return p.stock <= 3; }).map(function (p) { return { name: p.name, stock: p.stock }; }),
    recent_orders: orders.slice(0, 8)
  };
}
async function adminList(kind, params) {
  if (Api.live) {
    var act = { orders: 'getOrders', customers: 'getCustomers', tradeins: 'getTradeIns', logs: 'getLogs', products: 'getProducts', categories: 'getCategories', services: 'getServices', testimonials: 'getTestimonials', banners: 'getBanners', faqs: 'getFaqs' }[kind];
    var r = await Api.get(act, Object.assign({ key: undefined }, params || {}, { key: CONFIG.API_KEY }));
    if (kind === 'orders' || kind === 'products') return r.items || r;
    return r;
  }
  if (kind === 'products') return DB.products;
  if (kind === 'categories') return DB.categories;
  if (kind === 'services') return DB.services;
  if (kind === 'testimonials') return DB.testimonials;
  if (kind === 'banners') return DB.banners;
  if (kind === 'faqs') return DB.faqs;
  if (kind === 'orders') return DB.orders;
  if (kind === 'customers') return DB.customers;
  if (kind === 'tradeins') return DB.tradeins;
  if (kind === 'logs') return DEMO.logs;
  return [];
}
async function adminSave(kind, data) {
  if (Api.live) {
    var act = { products: 'upsertProduct', categories: 'upsertCategory', services: 'upsertService', testimonials: 'upsertTestimonial', banners: 'upsertBanner', faqs: 'upsertFaq', customers: 'upsertCustomer' }[kind];
    return Api.post({ action: act, token: SESSION.token, data: data });
  }
  var arr = DB[kind === 'products' ? 'products' : kind];
  if (!data.id) { data.id = uid('L'); (kind === 'products' ? DB.products : DB[kind]).unshift(data); }
  else {
    var i = DB[kind].findIndex(function (x) { return String(x.id) === String(data.id); });
    if (i !== -1) DB[kind][i] = Object.assign({}, DB[kind][i], data); else DB[kind].unshift(data);
  }
  if (kind === 'products') { var p = DB.products.find(function (x) { return String(x.id) === String(data.id); }); if (p) normProduct(p); }
  return data;
}
async function adminDelete(kind, id) {
  if (Api.live) {
    var act = { products: 'deleteProduct', categories: 'deleteCategory', services: 'deleteService', testimonials: 'deleteTestimonial', banners: 'deleteBanner', faqs: 'deleteFaq', customers: 'deleteCustomer', orders: 'deleteOrder' }[kind];
    return Api.post({ action: act, token: SESSION.token, id: id });
  }
  DB[kind] = DB[kind].filter(function (x) { return String(x.id) !== String(id); });
  return { deleted: true };
}
/* ---- form modal generik ---- */
function formModal(title, fields, values, onSave) {
  values = values || {};
  var html = '<h3 style="margin-bottom:16px">' + esc(title) + '</h3>';
  fields.forEach(function (f) {
    var v = values[f.k] !== undefined ? values[f.k] : (f.def || '');
    if (f.type === 'row') { html += '<div class="frow">'; return; }
    if (f.type === '/row') { html += '</div>'; return; }
    html += '<div class="field"><label>' + esc(f.label) + '</label>';
    if (f.type === 'textarea') html += '<textarea id="fm-' + f.k + '" placeholder="' + esc(f.ph || '') + '">' + esc(v) + '</textarea>';
    else if (f.type === 'select') html += '<select id="fm-' + f.k + '">' + f.opts.map(function (o) { return '<option value="' + esc(o[0]) + '"' + (String(v) === String(o[0]) ? ' selected' : '') + '>' + esc(o[1]) + '</option>'; }).join('') + '</select>';
    else if (f.type === 'check') html += '<label style="display:flex;gap:10px;align-items:center;font-weight:600"><input type="checkbox" id="fm-' + f.k + '" ' + (normBool(v) ? 'checked' : '') + ' style="width:20px;height:20px"/> ' + esc(f.hint || 'Ya') + '</label>';
    else html += '<input id="fm-' + f.k + '" type="' + (f.type || 'text') + '" placeholder="' + esc(f.ph || '') + '" value="' + esc(v) + '"/>';
    html += '</div>';
  });
  html += '<button class="btn btn-primary btn-block" id="fm-save" style="margin-top:6px"><i class="fa-solid fa-floppy-disk"></i> Simpan</button>';
  var m = openModal(html);
  $('#fm-save', m).onclick = async function () {
    var d = {};
    fields.forEach(function (f) {
      if (f.type === 'row' || f.type === '/row') return;
      var el = $('#fm-' + f.k, m); if (!el) return;
      d[f.k] = f.type === 'check' ? (el.checked ? 'TRUE' : 'FALSE') : el.value;
    });
    var btn = $('#fm-save', m); btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan…';
    try { await onSave(d); closeModal(); toast('Berhasil disimpan', 'success'); }
    catch (err) { toast(err.message || 'Gagal menyimpan', 'error'); btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan'; }
  };
}
/* ---- grafik batang canvas ---- */
function barChart(id, labels, values) {
  var c = document.getElementById(id); if (!c) return;
  var dpr = window.devicePixelRatio || 1, W = c.clientWidth || 600, H = 240;
  c.width = W * dpr; c.height = H * dpr; c.style.height = H + 'px';
  var x = c.getContext('2d'); x.scale(dpr, dpr);
  var max = Math.max.apply(null, values.concat([1]));
  var padL = 8, padB = 30, padT = 14, bw = (W - padL * 2) / values.length;
  var g = x.createLinearGradient(0, padT, 0, H - padB);
  g.addColorStop(0, '#7c3aed'); g.addColorStop(1, '#2563eb');
  values.forEach(function (v, i) {
    var h = Math.max(4, (H - padB - padT) * v / max);
    var bx = padL + i * bw + bw * 0.22, by = H - padB - h, wdt = bw * 0.56;
    x.fillStyle = '#e3eaf7';
    x.beginPath(); x.roundRect(padL + i * bw + bw * 0.22, padT, wdt, H - padB - padT, 6); x.fill();
    x.fillStyle = g;
    x.beginPath(); x.roundRect(bx, by, wdt, h, 6); x.fill();
    x.fillStyle = '#8ea0c2'; x.font = '11px Plus Jakarta Sans'; x.textAlign = 'center';
    x.fillText(labels[i], padL + i * bw + bw / 2, H - 10);
  });
}
