    ['Pesanan', d.orders_count, 'fa-receipt', 'linear-gradient(135deg,#059669,#34d399)'],
    ['Produk Aktif', d.products_count, 'fa-laptop', 'linear-gradient(135deg,#f59e0b,#fbbf24)'],
    ['Pelanggan', d.customers_count, 'fa-users', 'linear-gradient(135deg,#ec4899,#f472b6)']
  ];
  el.innerHTML = '<div class="stat-grid">' + cards.map(function (c) {
    return '<div class="stat"><span class="si" style="background:' + c[3] + '"><i class="fa-solid ' + c[2] + '"></i></span><span><b>' + c[1] + '</b><span>' + c[0] + '</span></span></div>';
  }).join('') + '</div>' +
    '<div class="grid2"><div class="card"><h3>Omzet 7 Hari Terakhir</h3><p class="sub">Hari ini: <b>' + fmtRp(d.today_revenue) + '</b> (' + d.today_orders + ' transaksi)</p><canvas id="ch7" style="width:100%"></canvas></div>' +
    '<div class="card"><h3>Produk Terlaris</h3><p class="sub">Berdasarkan total unit terjual</p>' +
    d.top_products.map(function (p, i) { return '<div style="display:flex;gap:12px;align-items:center;padding:9px 0;border-bottom:1px dashed var(--line)"><b style="color:var(--faint)">0' + (i + 1) + '</b><span style="flex:1;font-size:14px;font-weight:600">' + esc(p.name) + '</span><span class="badge b-blue">' + p.sold + ' terjual</span></div>'; }).join('') +
    '<h3 style="margin-top:18px">⚠️ Stok Menipis</h3><p class="sub">Segera restock sebelum kehabisan</p>' +
    (d.low_stock.length ? d.low_stock.map(function (p) { return '<div class="trow"><span>' + esc(p.name) + '</span><span class="badge b-amber">sisa ' + p.stock + '</span></div>'; }).join('') : '<p style="font-size:14px;color:var(--muted)">Semua stok aman. 🎉</p>') + '</div></div>' +
    '<div class="card"><h3>Pesanan Terbaru</h3><p class="sub"><a href="#/admin/orders" style="color:var(--brand);font-weight:700">Kelola semua pesanan →</a></p><div class="table-wrap"><table class="tbl"><thead><tr><th>Invoice</th><th>Pelanggan</th><th>Total</th><th>Status</th><th>Tanggal</th></tr></thead><tbody>' +
    d.recent_orders.map(function (o) { return '<tr><td><b>' + esc(o.invoice) + '</b><br/><span class="badge ' + (o.source === 'pos' ? 'b-purple' : 'b-blue') + '">' + (o.source === 'pos' ? 'POS' : 'Online') + '</span></td><td>' + esc(o.customer_name || '-') + '</td><td><b>' + fmtRp(o.total) + '</b></td><td><span class="badge ' + (o.payment_status === 'paid' ? 'b-green' : 'b-amber') + '">' + (o.payment_status === 'paid' ? 'Lunas' : 'Belum') + '</span> <span class="badge b-gray">' + esc(statusOrder(o.order_status)) + '</span></td><td style="font-size:13px">' + fmtDate(o.date || o.created_at) + '</td></tr>'; }).join('') +
    '</tbody></table></div></div>';
  barChart('ch7', d.chart7.map(function (x) { return new Date(x.date + 'T00:00').toLocaleDateString('id-ID', { weekday: 'short' }); }), d.chart7.map(function (x) { return x.total; }));
}
/* ---- Produk ---- */
var AP = { q: '' };
async function pProducts() {
  var el = $('#ap-products');
  el.innerHTML = '<div class="sk" style="height:300px"></div>';
  var list = await adminList('products');
  if (Api.live) list = (list.items || list).map ? (list.items || list).map(normProduct) : list;
  else list = DB.products;
  window._ap = list;
  var render = function () {
    var q = AP.q.toLowerCase();
    var rows = list.filter(function (p) { return !q || (p.name + ' ' + (p.sku || '') + ' ' + p.brand).toLowerCase().indexOf(q) !== -1; });
    el.innerHTML = '<div class="card"><div class="atoolbar"><div class="searchbox"><i class="fa-solid fa-magnifying-glass"></i><input id="ap-q" placeholder="Cari produk / SKU…" value="' + esc(AP.q) + '"/></div>' +
      '<span style="font-size:13.5px;color:var(--muted);font-weight:600">' + rows.length + ' produk</span>' +
      '<span style="flex:1"></span><button class="btn btn-primary btn-sm" id="ap-add"><i class="fa-solid fa-plus"></i> Tambah Produk</button></div>' +
      '<div class="table-wrap"><table class="tbl"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody>' +
      rows.map(function (p) {
        return '<tr><td><div style="display:flex;gap:11px;align-items:center"><img class="thumb" src="' + esc((p.images && p.images[0]) || p.image_url || '') + '" alt=""/><span><b>' + esc(p.name) + '</b><br/><span style="font-size:12px;color:var(--muted)">' + esc(p.sku || '') + ' • Terjual ' + (p.sold || 0) + '</span></span></div></td>' +
          '<td>' + esc(p.category || '-') + '<br/><span class="badge ' + (p.condition === 'second' ? 'b-amber' : 'b-blue') + '">' + (p.condition === 'second' ? 'Second' : 'Baru') + '</span></td>' +
          '<td><b>' + fmtRp(effP(p)) + '</b>' + (p.promo_price > 0 ? '<br/><span style="font-size:12px;color:var(--faint);text-decoration:line-through">' + fmtRp(p.price) + '</span>' : '') + '</td>' +
          '<td><b style="color:' + (p.stock <= 0 ? 'var(--danger)' : p.stock <= 3 ? 'var(--warn)' : 'var(--success)') + '">' + p.stock + '</b><br/><button class="mini-btn" data-stock="' + esc(p.id) + '" title="Atur stok" style="width:auto;padding:0 10px;height:28px;font-size:12px;font-weight:700">Atur</button></td>' +
          '<td><span class="badge ' + ((p.status || 'active') === 'active' ? 'b-green' : 'b-gray') + '">' + ((p.status || 'active') === 'active' ? 'Aktif' : p.status) + '</span>' + (p.bestseller ? ' <span class="badge b-purple">BS</span>' : '') + (p.featured ? ' <span class="badge b-blue">FT</span>' : '') + '</td>' +
          '<td><div class="rowbtns"><button class="mini-btn edit" data-edit="' + esc(p.id) + '" title="Edit"><i class="fa-solid fa-pen"></i></button><button class="mini-btn del" data-del="' + esc(p.id) + '" title="Hapus"><i class="fa-solid fa-trash"></i></button></div></td></tr>';
      }).join('') + '</tbody></table></div></div>';
    $('#ap-q').oninput = debounce(function (e) { AP.q = e.target.value; render(); var nq = $('#ap-q'); nq.focus(); nq.setSelectionRange(nq.value.length, nq.value.length); }, 350);
    $('#ap-add').onclick = function () { productForm(null, list, render); };
    $$('[data-edit]', el).forEach(function (b) { b.onclick = function () { productForm(list.find(function (x) { return String(x.id) === b.dataset.edit; }), list, render); }; });
    $$('[data-del]', el).forEach(function (b) { b.onclick = async function () { if (await confirmDlg('Hapus produk?', 'Produk akan dihapus permanen dari katalog.', 'Ya, hapus')) { await adminDelete('products', b.dataset.del); toast('Produk dihapus', 'success'); pProducts(); Store.init().then(renderStorefront); } }; });
    $$('[data-stock]', el).forEach(function (b) { b.onclick = function () { stockForm(b.dataset.stock); }; });
  };
  render();
}
function productForm(p, list, rerender) {
  var cats = (DB.categories.length ? DB.categories : DEMO.categories).map(function (c) { return [c.name, c.name]; });
  formModal(p ? 'Edit Produk' : 'Tambah Produk', [
    { k: 'name', label: 'Nama produk *', ph: 'cth: ASUS VivoBook 14 OLED' },
    { k: 'row', label: '' }, { k: 'brand', label: 'Merek', ph: 'ASUS' }, { k: 'category', label: 'Kategori', type: 'select', opts: cats }, { k: '/row', label: '' },
    { k: 'row', label: '' }, { k: 'price', label: 'Harga normal (Rp)', type: 'number', ph: '9500000' }, { k: 'promo_price', label: 'Harga promo (0 = tidak ada)', type: 'number', def: '0' }, { k: '/row', label: '' },
    { k: 'row', label: '' }, { k: 'stock', label: 'Stok', type: 'number', def: '0' }, { k: 'condition', label: 'Kondisi', type: 'select', opts: [['new', 'Baru'], ['second', 'Second']] }, { k: '/row', label: '' },
    { k: 'specs', label: 'Spesifikasi singkat', ph: 'i5 • 16GB • 512GB SSD' },
    { k: 'description', label: 'Deskripsi', type: 'textarea' },
    { k: 'image_url', label: 'URL foto utama', ph: 'https://…' },
    { k: 'row', label: '' }, { k: 'badge', label: 'Badge (opsional)', ph: 'Best Seller / -10% / Second Mulus' }, { k: 'status', label: 'Status', type: 'select', opts: [['active', 'Aktif'], ['draft', 'Draft'], ['archived', 'Arsip']] }, { k: '/row', label: '' },
    { k: 'row', label: '' }, { k: 'featured', label: 'Unggulan?', type: 'check', hint: 'Tampil di pilihan editor' }, { k: 'bestseller', label: 'Terlaris?', type: 'check', hint: 'Label best seller' }, { k: '/row', label: '' }
  ], p || {}, async function (d) {
    if (!d.name) throw new Error('Nama produk wajib diisi');
    if (p && p.id) d.id = p.id;
    if (!d.image_url) d.image_url = U('photo-1496181133206-80ce9b88a853');
    d.images = d.image_url;
    await adminSave('products', d);
    if (!Api.live) { var ex = DB.products.find(function (x) { return x.id === d.id; }); if (!ex && d.id) normProduct(d); }
    else { try { var pr = await Api.get('getProducts', { limit: 100 }); DB.products = (pr.items || []).map(normProduct); } catch (e) {} }
    renderStorefront(); pProducts();
  });
}
function stockForm(id) {
  var p = DB.products.find(function (x) { return String(x.id) === String(id); });
  if (!p) return;
  formModal('Atur Stok — ' + p.name, [
    { k: 'mode', label: 'Mode', type: 'select', opts: [['add', 'Tambah stok'], ['sub', 'Kurangi stok'], ['set', 'Set angka pasti']] },
    { k: 'qty', label: 'Jumlah', type: 'number', def: '1' }
  ], {}, async function (d) {
    var q = Number(d.qty || 0);
    if (Api.live) await Api.post({ action: 'adjustStock', token: SESSION.token, id: id, qty: d.mode === 'sub' ? -q : q, mode: d.mode === 'set' ? 'set' : 'add' });
    else {
      if (d.mode === 'set') p.stock = q; else if (d.mode === 'sub') p.stock = Math.max(0, p.stock - q); else p.stock += q;
    }
    renderStorefront(); pProducts();
  });
}
