  el.innerHTML = '<div class="card"><div class="atoolbar"><span style="font-size:13.5px;color:var(--muted);font-weight:600">' + list.length + ' kategori</span><span style="flex:1"></span><button class="btn btn-primary btn-sm" id="ct-add"><i class="fa-solid fa-plus"></i> Tambah Kategori</button></div>' +
    '<div class="table-wrap"><table class="tbl"><thead><tr><th>Kategori</th><th>Slug</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>' +
    list.map(function (c) { return '<tr><td><b>' + esc(c.icon || '📦') + ' ' + esc(c.name) + '</b><br/><span style="font-size:12px;color:var(--muted)">' + esc(c.description || '') + '</span></td><td><code>' + esc(c.slug || '') + '</code></td><td>' + (c.sort || '-') + '</td><td><span class="badge ' + ((c.status || 'active') === 'active' ? 'b-green' : 'b-gray') + '">' + (c.status || 'active') + '</span></td><td><div class="rowbtns"><button class="mini-btn edit" data-e="' + esc(c.id) + '"><i class="fa-solid fa-pen"></i></button><button class="mini-btn del" data-d="' + esc(c.id) + '"><i class="fa-solid fa-trash"></i></button></div></td></tr>'; }).join('') +
    '</tbody></table></div></div>';
  $('#ct-add').onclick = function () { catForm(null); };
  $$('[data-e]', el).forEach(function (b) { b.onclick = function () { catForm(list.find(function (x) { return String(x.id) === b.dataset.e; })); }; });
  $$('[data-d]', el).forEach(function (b) { b.onclick = async function () { if (await confirmDlg('Hapus kategori?', 'Kategori akan dihapus.', 'Ya, hapus')) { await adminDelete('categories', b.dataset.d); toast('Kategori dihapus', 'success'); pCategories(); } }; });
}
function catForm(c) {
  formModal(c ? 'Edit Kategori' : 'Tambah Kategori', [
    { k: 'name', label: 'Nama kategori *' },
    { k: 'row', label: '' }, { k: 'icon', label: 'Ikon (emoji)', ph: '💻' }, { k: 'sort', label: 'Urutan', type: 'number', def: '1' }, { k: '/row', label: '' },
    { k: 'description', label: 'Deskripsi' },
    { k: 'status', label: 'Status', type: 'select', opts: [['active', 'Aktif'], ['draft', 'Nonaktif']] }
  ], c || {}, async function (d) {
    if (!d.name) throw new Error('Nama wajib diisi');
    if (c && c.id) d.id = c.id;
    await adminSave('categories', d);
    if (Api.live) { try { DB.categories = await Api.get('getCategories'); } catch (e) {} }
    renderCats(); pCategories();
  });
}
/* ---- Pesanan ---- */
var AO = { q: '', status: '', source: '' };
async function pOrders() {
  var el = $('#ap-orders');
  el.innerHTML = '<div class="sk" style="height:300px"></div>';
  var list = await adminList('orders', { limit: 100 });
  var render = function () {
    var rows = list.filter(function (o) {
      if (AO.status && o.order_status !== AO.status) return false;
      if (AO.source && o.source !== AO.source) return false;
      if (AO.q && (String(o.invoice) + ' ' + String(o.customer_name || '')).toLowerCase().indexOf(AO.q.toLowerCase()) === -1) return false;
      return true;
    });
    el.innerHTML = '<div class="card"><div class="atoolbar"><div class="searchbox"><i class="fa-solid fa-magnifying-glass"></i><input id="ao-q" placeholder="Cari invoice / nama…" value="' + esc(AO.q) + '"/></div>' +
      '<select class="select" id="ao-st"><option value="">Semua status</option>' + ['pending', 'paid', 'process', 'shipped', 'completed', 'cancelled'].map(function (s) { return '<option value="' + s + '"' + (AO.status === s ? ' selected' : '') + '>' + statusOrder(s) + '</option>'; }).join('') + '</select>' +
      '<select class="select" id="ao-src"><option value="">Online + POS</option><option value="online"' + (AO.source === 'online' ? ' selected' : '') + '>Online</option><option value="pos"' + (AO.source === 'pos' ? ' selected' : '') + '>POS</option></select>' +
      '<span style="font-size:13px;color:var(--muted);font-weight:700">' + rows.length + ' order</span></div>' +
      '<div class="table-wrap"><table class="tbl"><thead><tr><th>Invoice</th><th>Pelanggan</th><th>Total</th><th>Bayar</th><th>Status</th><th>Aksi</th></tr></thead><tbody>' +
      rows.map(function (o) {
        return '<tr><td><b>' + esc(o.invoice) + '</b><br/><span class="badge ' + (o.source === 'pos' ? 'b-purple' : 'b-blue') + '">' + (o.source === 'pos' ? 'POS' : 'Online') + '</span> <span style="font-size:12px;color:var(--muted)">' + fmtDate(o.date || o.created_at) + '</span></td>' +
          '<td>' + esc(o.customer_name || '-') + '<br/><span style="font-size:12px;color:var(--muted)">' + esc(o.customer_wa || '') + '</span></td>' +
          '<td><b>' + fmtRp(o.total) + '</b><br/><span style="font-size:12px;color:var(--muted)">' + esc(o.payment_method || '') + '</span></td>' +
          '<td><span class="badge ' + (o.payment_status === 'paid' ? 'b-green' : 'b-amber') + '">' + (o.payment_status === 'paid' ? 'Lunas' : 'Belum') + '</span></td>' +
          '<td><span class="badge b-gray">' + esc(statusOrder(o.order_status)) + '</span></td>' +
          '<td><div class="rowbtns"><button class="mini-btn view" data-v="' + esc(o.id) + '" title="Detail"><i class="fa-solid fa-eye"></i></button>' +
          (o.payment_status !== 'paid' ? '<button class="mini-btn edit" data-paid="' + esc(o.id) + '" title="Tandai lunas"><i class="fa-solid fa-money-bill-wave"></i></button>' : '') +
          '<button class="mini-btn edit" data-nx="' + esc(o.id) + '" title="Status berikutnya"><i class="fa-solid fa-forward"></i></button>' +
          '<button class="mini-btn del" data-x="' + esc(o.id) + '" title="Batalkan"><i class="fa-solid fa-ban"></i></button></div></td></tr>';
      }).join('') + '</tbody></table></div></div>';
    $('#ao-q').oninput = debounce(function (e) { AO.q = e.target.value; render(); var nq = $('#ao-q'); nq.focus(); nq.setSelectionRange(nq.value.length, nq.value.length); }, 350);
    $('#ao-st').onchange = function (e) { AO.status = e.target.value; render(); };
    $('#ao-src').onchange = function (e) { AO.source = e.target.value; render(); };
    $$('[data-v]', el).forEach(function (b) { b.onclick = function () { orderDetail(list.find(function (x) { return String(x.id) === b.dataset.v; })); }; });
    $$('[data-paid]', el).forEach(function (b) { b.onclick = function () { orderUpdate(b.dataset.paid, { payment_status: 'paid', order_status: 'process' }, list); }; });
    $$('[data-nx]', el).forEach(function (b) {
      b.onclick = function () {
        var o = list.find(function (x) { return String(x.id) === b.dataset.nx; });
        var flow = ['pending', 'process', 'shipped', 'completed'];
        var nx = flow[Math.min(flow.indexOf(o.order_status) + 1, 3)] || 'process';
        orderUpdate(o.id, { order_status: nx }, list);
      };
    });
    $$('[data-x]', el).forEach(function (b) { b.onclick = async function () { if (await confirmDlg('Batalkan pesanan?', 'Stok akan dikembalikan otomatis.', 'Ya, batalkan')) orderUpdate(b.dataset.x, { order_status: 'cancelled' }, list); }; });
  };
  render();
}
async function orderUpdate(id, patch, list) {
  try {
    if (Api.live) await Api.post(Object.assign({ action: 'updateOrder', token: SESSION.token, id: id }, patch));
    else { var o = list.find(function (x) { return String(x.id) === String(id); }); if (o) Object.assign(o, patch); }
    toast('Pesanan diperbarui', 'success'); pOrders(); Admin.refreshBadges();
  } catch (err) { toast(err.message, 'error'); }
}
function orderDetail(o) {
  var items = [];
  try { items = o.items || JSON.parse(o.items_json || '[]'); } catch (e) {}
  openModal('<h3 style="margin-bottom:2px">' + esc(o.invoice) + '</h3><p style="color:var(--muted);font-size:13.5px;margin-bottom:14px">' + fmtDate(o.date || o.created_at) + ' • Sumber: ' + esc(o.source || 'online') + (o.cashier ? ' • Kasir: ' + esc(o.cashier) : '') + '</p>' +
    '<div style="background:#f8faff;border-radius:12px;padding:14px;margin-bottom:14px;font-size:14px"><b>' + esc(o.customer_name || '-') + '</b><br/>' + esc(o.customer_wa || '') + '<br/>' + esc(o.customer_address || '') + (o.notes ? '<br/><i>Catatan: ' + esc(o.notes) + '</i>' : '') + '</div>' +
    items.map(function (it) { return '<div class="trow"><span>' + esc(it.name) + ' ×' + it.qty + '</span><b style="color:var(--ink)">' + fmtRp(it.subtotal || 0) + '</b></div>'; }).join('') +
    '<div class="trow"><span>Subtotal</span><span>' + fmtRp(o.subtotal || o.total) + '</span></div>' +
    '<div class="trow"><span>Diskon</span><span>-' + fmtRp(o.discount || 0) + '</span></div>' +
    '<div class="trow"><span>Ongkir</span><span>' + fmtRp(o.shipping || 0) + '</span></div>' +
    '<div class="trow grand"><span>Total</span><span>' + fmtRp(o.total) + '</span></div>' +
    '<div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><span class="badge ' + (o.payment_status === 'paid' ? 'b-green' : 'b-amber') + '">' + (o.payment_status === 'paid' ? 'Lunas' : 'Belum bayar') + '</span><span class="badge b-blue">' + esc(statusOrder(o.order_status)) + '</span><span class="badge b-gray">' + esc(o.payment_method || '') + '</span></div>' +
    (o.customer_wa ? '<a class="btn btn-success btn-block" style="margin-top:14px" target="_blank" rel="noopener" href="https://wa.me/' + esc(String(o.customer_wa).replace(/[^0-9]/g, '')) + '?text=' + encodeURIComponent('Halo ' + (o.customer_name || '') + ', ini dari ' + SETTINGS.store_name + ' terkait pesanan ' + o.invoice + '.') + '"><i class="fa-brands fa-whatsapp"></i> Hubungi Pelanggan</a>' : ''));
}
