  el.innerHTML = '<div class="card"><div class="atoolbar"><span style="font-size:13.5px;color:var(--muted);font-weight:600">' + list.length + ' pengajuan</span></div>' +
    '<div class="table-wrap"><table class="tbl"><thead><tr><th>Tanggal</th><th>Pelanggan</th><th>Device</th><th>Estimasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>' +
    list.map(function (t) {
