      return '<tr><td style="font-size:13px">' + fmtDate(t.date || t.created_at) + '</td><td><b>' + esc(t.name) + '</b><br/><span style="font-size:12px;color:var(--muted)">' + esc(t.wa || '') + '</span></td>' +
        '<td><b>' + esc(t.device_brand || '') + ' ' + esc(t.device_model || '') + '</b><br/><span style="font-size:12px;color:var(--muted)">' + esc(t.condition || '') + ' — ' + esc(t.description || '') + '</span></td>' +
        '<td><b>' + (t.est_price ? fmtRp(t.est_price) : '-') + '</b></td><td><span class="badge ' + bc + '">' + esc(t.status || 'pending') + '</span></td>' +
        '<td><div class="rowbtns"><button class="mini-btn edit" data-e="' + esc(t.id) + '" title="Proses"><i class="fa-solid fa-pen"></i></button><a class="mini-btn view" target="_blank" rel="noopener" href="https://wa.me/' + esc(String(t.wa || '').replace(/[^0-9]/g, '')) + '" title="Chat WA"><i class="fa-brands fa-whatsapp"></i></a></div></td></tr>';
    }).join('') + '</tbody></table></div></div>';
  $$('[data-e]', el).forEach(function (b) {
    b.onclick = function () {
      var t = list.find(function (x) { return String(x.id) === b.dataset.e; });
      formModal('Proses Trade-In — ' + t.name, [
        { k: 'est_price', label: 'Harga penawaran (Rp)', type: 'number', def: t.est_price || '' },
        { k: 'status', label: 'Status', type: 'select', opts: [['pending', 'Pending'], ['approved', 'Deal / Disetujui'], ['rejected', 'Ditolak'], ['done', 'Selesai (unit diterima)']] },
        { k: 'notes', label: 'Catatan internal', type: 'textarea' }
      ], { status: t.status, notes: t.notes }, async function (d) {
        if (Api.live) await Api.post({ action: 'updateTradeIn', token: SESSION.token, id: t.id, status: d.status, est_price: Number(d.est_price || 0), notes: d.notes });
        else Object.assign(t, { status: d.status, est_price: Number(d.est_price || 0), notes: d.notes });
        pTradein(); Admin.refreshBadges();
      });
