/* ---- Pelanggan ---- */
async function pCustomers() {
  var el = $('#ap-customers');
  var list = await adminList('customers');
  el.innerHTML = '<div class="card"><div class="atoolbar"><span style="font-size:13.5px;color:var(--muted);font-weight:600">' + list.length + ' pelanggan</span><span style="flex:1"></span><button class="btn btn-primary btn-sm" id="cu-add"><i class="fa-solid fa-plus"></i> Tambah</button></div>' +
    '<div class="table-wrap"><table class="tbl"><thead><tr><th>Nama</th><th>Kontak</th><th>Order</th><th>Total Belanja</th><th>Aksi</th></tr></thead><tbody>' +
    list.map(function (c) { return '<tr><td><div style="display:flex;gap:10px;align-items:center"><span class="avatar" style="width:38px;height:38px;font-size:14px">' + esc(initials(c.name)) + '</span><b>' + esc(c.name) + '</b></div></td><td>' + esc(c.wa || '-') + '<br/><span style="font-size:12px;color:var(--muted)">' + esc(c.email || c.address || '') + '</span></td><td><b>' + (c.total_orders || 0) + '</b></td><td><b>' + fmtRp(c.total_spend || 0) + '</b></td><td><div class="rowbtns"><button class="mini-btn edit" data-e="' + esc(c.id) + '"><i class="fa-solid fa-pen"></i></button><button class="mini-btn del" data-d="' + esc(c.id) + '"><i class="fa-solid fa-trash"></i></button></div></td></tr>'; }).join('') +
    '</tbody></table></div></div>';
  $('#cu-add').onclick = function () { custForm(null); };
  $$('[data-e]', el).forEach(function (b) { b.onclick = function () { custForm(list.find(function (x) { return String(x.id) === b.dataset.e; })); }; });
  $$('[data-d]', el).forEach(function (b) { b.onclick = async function () { if (await confirmDlg('Hapus pelanggan?', 'Data pelanggan akan dihapus.', 'Ya, hapus')) { await adminDelete('customers', b.dataset.d); pCustomers(); } }; });
}
function custForm(c) {
  formModal(c ? 'Edit Pelanggan' : 'Tambah Pelanggan', [
    { k: 'name', label: 'Nama *' },
    { k: 'row', label: '' }, { k: 'wa', label: 'WhatsApp' }, { k: 'email', label: 'Email' }, { k: '/row', label: '' },
    { k: 'address', label: 'Alamat', type: 'textarea' }
  ], c || {}, async function (d) {
    if (!d.name) throw new Error('Nama wajib diisi');
    if (c && c.id) d.id = c.id;
    await adminSave('customers', d); pCustomers();
  });
}
/* ---- Laporan ---- */
async function pReports() {
  var el = $('#ap-reports');
  el.innerHTML = '<div class="sk" style="height:300px"></div>';
  var rows;
  if (Api.live) { try { rows = await Api.get('getReport', { period: 'daily' }); } catch (e) { rows = []; } }
  else {
    var g = {};
    DEMO.orders.filter(function (o) { return o.payment_status === 'paid'; }).forEach(function (o) {
      var k = String(o.date).slice(0, 10);
      if (!g[k]) g[k] = { period: k, omzet: 0, transaksi: 0, items: 0, by_payment: {}, by_source: {} };
      g[k].omzet += Number(o.total); g[k].transaksi += 1; g[k].items += 1;
      g[k].by_payment[o.payment_method] = (g[k].by_payment[o.payment_method] || 0) + 1;
    });
    rows = Object.keys(g).sort().reverse().map(function (k) { return g[k]; });
  }
  var tot = rows.reduce(function (s, r) { return s + r.omzet; }, 0);
  var trx = rows.reduce(function (s, r) { return s + r.transaksi; }, 0);
  el.innerHTML = '<div class="stat-grid" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><span class="si" style="background:linear-gradient(135deg,#2563eb,#7c3aed)"><i class="fa-solid fa-sack-dollar"></i></span><span><b>' + fmtRp(tot) + '</b><span>Total omzet tercatat</span></span></div>' +
    '<div class="stat"><span class="si" style="background:linear-gradient(135deg,#059669,#34d399)"><i class="fa-solid fa-receipt"></i></span><span><b>' + trx + '</b><span>Total transaksi</span></span></div>' +
    '<div class="stat"><span class="si" style="background:linear-gradient(135deg,#f59e0b,#fbbf24)"><i class="fa-solid fa-calculator"></i></span><span><b>' + fmtRp(trx ? tot / trx : 0) + '</b><span>Rata-rata / transaksi</span></span></div></div>' +
    '<div class="card"><h3>Omzet Harian</h3><p class="sub">Klik periode untuk detail (demo menampilkan ringkasan)</p><canvas id="chr" style="width:100%"></canvas></div>' +
    '<div class="card"><h3>Riwayat Periode</h3><div class="table-wrap"><table class="tbl"><thead><tr><th>Periode</th><th>Omzet</th><th>Transaksi</th><th>Item</th><th>Via</th></tr></thead><tbody>' +
    rows.map(function (r) { return '<tr><td><b>' + esc(r.period) + '</b></td><td><b>' + fmtRp(r.omzet) + '</b></td><td>' + r.transaksi + '</td><td>' + r.items + '</td><td style="font-size:12.5px">' + Object.keys(r.by_payment || {}).map(function (k) { return k + '×' + r.by_payment[k]; }).join(', ') + '</td></tr>'; }).join('') +
    '</tbody></table></div></div>';
  barChart('chr', rows.slice(0, 14).reverse().map(function (r) { return String(r.period).slice(5); }), rows.slice(0, 14).reverse().map(function (r) { return r.omzet; }));
}
/* ---- CRUD konten generik (layanan/testimoni/banner/faq) ---- */
function contentPage(kind, title, cols, fields, onChange) {
  return async function () {
    var el = $('#ap-' + (kind === 'testimonials' ? 'testimonials' : kind === 'faqs' ? 'faqs' : kind === 'services' ? 'services' : 'banners'));
    var list = await adminList(kind);
    el.innerHTML = '<div class="card"><div class="atoolbar"><span style="font-size:13.5px;color:var(--muted);font-weight:600">' + list.length + ' ' + title.toLowerCase() + '</span><span style="flex:1"></span><button class="btn btn-primary btn-sm" id="cx-add"><i class="fa-solid fa-plus"></i> Tambah</button></div>' +
      '<div class="table-wrap"><table class="tbl"><thead><tr>' + cols.map(function (c) { return '<th>' + c[1] + '</th>'; }).join('') + '<th>Aksi</th></tr></thead><tbody>' +
      list.map(function (r) {
        return '<tr>' + cols.map(function (c) { return '<td>' + c[2](r) + '</td>'; }).join('') +
          '<td><div class="rowbtns"><button class="mini-btn edit" data-e="' + esc(r.id) + '"><i class="fa-solid fa-pen"></i></button><button class="mini-btn del" data-d="' + esc(r.id) + '"><i class="fa-solid fa-trash"></i></button></div></td></tr>';
      }).join('') + '</tbody></table></div></div>';
    $('#cx-add').onclick = function () {
      formModal('Tambah ' + title, fields, {}, async function (d) { await adminSave(kind, d); await afterCx(); });
    };
    $$('[data-e]', el).forEach(function (b) { b.onclick = function () { formModal('Edit ' + title, fields, list.find(function (x) { return String(x.id) === b.dataset.e; }), async function (d) { d.id = b.dataset.e; await adminSave(kind, d); await afterCx(); }); }; });
    $$('[data-d]', el).forEach(function (b) { b.onclick = async function () { if (await confirmDlg('Hapus data?', 'Data akan dihapus dari website.', 'Ya, hapus')) { await adminDelete(kind, b.dataset.d); await afterCx(); } }; });
    async function afterCx() {
      if (Api.live) { try { DB[kind] = await Api.get({ services: 'getServices', testimonials: 'getTestimonials', banners: 'getBanners', faqs: 'getFaqs' }[kind]); } catch (e) {} }
      if (onChange) onChange();
      Admin.goto(APAGE);
    }
  };
}
