/* ---- Pengaturan ---- */
async function pSettings() {
  var el = $('#ap-settings');
  var s = Object.assign({}, SETTINGS);
  if (Api.live) { try { s = Object.assign(s, await Api.get('getSettings', {})); } catch (e) {} }
  var FIELDS = [
    ['store_name', 'Nama toko', 'text'], ['store_tagline', 'Tagline toko', 'text'],
    ['store_wa', 'No. WhatsApp toko', 'text'], ['store_email', 'Email toko', 'text'],
    ['store_address', 'Alamat toko', 'textarea'], ['store_hours', 'Jam operasional', 'text'],
    ['hero_title', 'Judul hero', 'text'], ['hero_subtitle', 'Subjudul hero', 'textarea'],
    ['announcement', 'Teks pengumuman (HTML)', 'textarea'],
    ['shipping_flat', 'Ongkir flat (Rp)', 'number'], ['free_shipping_min', 'Min. gratis ongkir (Rp)', 'number'],
    ['bank_info', 'Info pembayaran', 'textarea'],
    ['admin_user', 'Username admin', 'text'], ['pos_pin', 'PIN kasir', 'text']
  ];
  el.innerHTML = '<div class="grid2"><div class="card"><h3>Koneksi Backend</h3><p class="sub">Hubungkan tema ke Google Apps Script agar data live.</p>' +
    '<div class="field"><label>Web App URL (Apps Script)</label><input id="set-url" placeholder="https://script.google.com/macros/s/…/exec" value="' + esc(CONFIG.API_URL) + '"/></div>' +
    '<div class="field"><label>API Key</label><input id="set-key" placeholder="API key dari fungsi setup()" value="' + esc(CONFIG.API_KEY) + '"/></div>' +
    '<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn btn-primary btn-sm" id="set-conn"><i class="fa-solid fa-plug"></i> Simpan &amp; Sambungkan</button>' +
    '<button class="btn btn-outline btn-sm" id="set-test"><i class="fa-solid fa-heart-pulse"></i> Tes Koneksi</button></div>' +
    '<div id="set-msg" style="font-size:13.5px;margin-top:12px;font-weight:600"></div>' +
    (Api.live ? '<button class="btn btn-ghost btn-sm" id="set-seed" style="margin-top:14px"><i class="fa-solid fa-database"></i> Isi data demo ke Spreadsheet</button>' : '') + '</div>' +
    '<div class="card"><h3>Profil Toko &amp; Website</h3><p class="sub">Perubahan tampil langsung di toko.</p><div id="set-fields">' +
    FIELDS.map(function (f) {
      var v = s[f[0]] || '';
      if (f[2] === 'textarea') return '<div class="field"><label>' + f[1] + '</label><textarea id="set-' + f[0] + '">' + esc(v) + '</textarea></div>';
      return '<div class="field"><label>' + f[1] + '</label><input id="set-' + f[0] + '" type="' + f[2] + '" value="' + esc(v) + '"/></div>';
    }).join('') +
    '<div class="field"><label>Password admin baru (kosongkan jika tidak diubah)</label><input id="set-pass" type="password" placeholder="••••••••"/></div>' +
    '<button class="btn btn-primary" id="set-save"><i class="fa-solid fa-floppy-disk"></i> Simpan Pengaturan</button></div></div></div>';
  $('#set-conn').onclick = function () {
    CONFIG.API_URL = $('#set-url').value.trim(); CONFIG.API_KEY = $('#set-key').value.trim();
    localStorage.setItem('laptorium_cfg', JSON.stringify({ API_URL: CONFIG.API_URL, API_KEY: CONFIG.API_KEY }));
    toast('Menyambungkan…'); location.reload();
  };
  $('#set-test').onclick = async function () {
    var m = $('#set-msg'); m.textContent = 'Menghubungi server…';
    try {
      var url = $('#set-url').value.trim(), key = $('#set-key').value.trim();
      var r = await fetch(url + '?action=health&key=' + encodeURIComponent(key));
      var j = await r.json();
      m.innerHTML = j.ok ? '<span style="color:var(--success)">✅ Terhubung! ' + esc(j.data.app) + ' v' + esc(j.data.version) + '</span>' : '<span style="color:var(--danger)">❌ ' + esc(j.error) + '</span>';
    } catch (e) { m.innerHTML = '<span style="color:var(--danger)">❌ Gagal: periksa URL &amp; akses deploy (Anyone).</span>'; }
  };
  var seed = $('#set-seed');
  if (seed) seed.onclick = async function () {
    if (!await confirmDlg('Isi data demo?', 'Spreadsheet akan diisi kategori, produk, layanan, testimoni, banner, & FAQ contoh.', 'Ya, isi')) return;
    try { await Api.post({ action: 'seedDemo', token: SESSION.token }); toast('Data demo berhasil diisi. Memuat ulang…', 'success'); setTimeout(function () { location.reload(); }, 1200); }
    catch (e) { toast(e.message, 'error'); }
  };
  $('#set-save').onclick = async function () {
    var d = {};
    FIELDS.forEach(function (f) { var e2 = $('#set-' + f[0]); if (e2) d[f[0]] = e2.value; });
    var np = $('#set-pass').value; if (np) d.admin_pass_new = np;
    try {
      if (Api.live) { SETTINGS = Object.assign({}, SETTINGS, await Api.post({ action: 'saveSettings', token: SESSION.token, data: d })); }
      else SETTINGS = Object.assign({}, SETTINGS, d);
      applySettings(); toast('Pengaturan disimpan', 'success');
    } catch (e) { toast(e.message, 'error'); }
  };
}
