    '</tbody></table></div></div>';
}

/* ================= POS KASIR ================= */
var POS = {
  items: [], cat: '', q: '', pay: 'cash',
  enter() {
    var ok = SESSION.token && (SESSION.role === 'kasir' || SESSION.role === 'admin');
    if (!Api.live) ok = ok || sessionStorage.getItem('laptorium_demo_pos') === '1';
    $('#pos-login').style.display = ok ? 'none' : '';
    $('#pos-app').style.display = ok ? '' : 'none';
    if (!ok) return;
    $('#pos-user').textContent = SESSION.name || 'Kasir';
    $('#pos-status').textContent = Api.live ? '● Live' : '● Demo';
    this.renderCats(); this.renderGrid(); this.renderCart(); this.renderPay(); this.clock();
  },
  login(ev) {
    ev.preventDefault();
    var name = $('#pos-name').value.trim() || 'Kasir', pin = $('#pos-pin').value.trim();
    var done = function () {
      toast('Kasir dibuka. Selamat bertugas, ' + name + '!', 'success');
      POS.enter();
    };
    if (Api.live) {
      Api.post({ action: 'login', mode: 'pos', pin: pin, cashier: name }).then(function (r) {
        saveSession(r.token, r.role, r.name); done();
      }).catch(function (e) { toast(e.message, 'error'); });
    } else {
      if (pin !== '1234') { toast('PIN salah. (Demo: 1234)', 'error'); return; }
      sessionStorage.setItem('laptorium_demo_pos', '1');
      saveSession('demo', 'kasir', name); done();
    }
  },
  clock() {
    var tick = function () {
      var el = $('#pos-clock'); if (!el) return;
      el.textContent = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    };
    tick(); setInterval(tick, 1000);
  },
  renderCats() {
    var box = $('#pos-cats');
    box.innerHTML = '<button class="pill' + (this.cat === '' ? ' active' : '') + '" data-pcat="">Semua</button>' +
      DB.categories.map(function (c) { return '<button class="pill' + (POS.cat === c.name ? ' active' : '') + '" data-pcat="' + esc(c.name) + '">' + esc(c.icon || '') + ' ' + esc(c.name) + '</button>'; }).join('');
    $$('[data-pcat]', box).forEach(function (b) { b.onclick = function () { POS.cat = b.dataset.pcat; POS.renderCats(); POS.renderGrid(); }; });
  },
  filtered() {
    var self = this;
    return DB.products.filter(function (p) {
      if ((p.status || 'active') !== 'active') return false;
      if (self.cat && p.category !== self.cat) return false;
      if (self.q && (p.name + ' ' + (p.sku || '')).toLowerCase().indexOf(self.q.toLowerCase()) === -1) return false;
      return true;
    });
  },
  renderGrid() {
    var list = this.filtered();
    $('#pos-grid').innerHTML = list.length ? list.map(function (p) {
      return '<button class="pos-item' + (p.stock <= 0 ? ' out' : '') + '" data-padd="' + esc(p.id) + '"' + (p.stock <= 0 ? ' disabled' : '') + '>' +
        '<img src="' + esc((p.images && p.images[0]) || p.image_url || '') + '" alt="" loading="lazy"/><b>' + esc(p.name) + '</b>' +
        '<span class="pp">' + fmtRp(effP(p)) + '</span><span class="ps">' + (p.stock <= 0 ? 'Habis' : 'Stok: ' + p.stock) + '</span></button>';
    }).join('') : '<div class="empty" style="grid-column:1/-1"><i class="fa-solid fa-box-open"></i><p>Produk tidak ditemukan.</p></div>';
    $$('#pos-grid [data-padd]').forEach(function (b) { b.onclick = function () { POS.add(b.dataset.padd); }; });
  },
  add(id) {
    var p = DB.products.find(function (x) { return String(x.id) === String(id); });
    if (!p || p.stock <= 0) { toast('Stok habis', 'error'); return; }
    var ex = this.items.find(function (it) { return String(it.id) === String(id); });
    if (ex) { if (ex.qty + 1 > p.stock) { toast('Stok hanya ' + p.stock, 'warn'); return; } ex.qty++; }
    else this.items.push({ id: String(id), qty: 1 });
    this.renderCart();
  },
  renderCart() {
    var self = this;
    var box = $('#pos-items');
    if (!this.items.length) {
      box.innerHTML = '<div class="empty"><i class="fa-solid fa-cart-shopping"></i><p>Belum ada item.<br/>Ketuk produk untuk menambah.</p></div>';
    } else {
      box.innerHTML = this.items.map(function (it) {
        var p = DB.products.find(function (x) { return String(x.id) === String(it.id); });
        return '<div class="citem"><img src="' + esc((p.images && p.images[0]) || '') + '" alt=""/><div class="ci"><b>' + esc(p.name) + '</b><div class="cp">' + fmtRp(effP(p)) + '</div><span class="qty"><button data-pdec="' + esc(p.id) + '">−</button><span>' + it.qty + '</span><button data-pinc="' + esc(p.id) + '">+</button></span></div><div style="text-align:right"><b style="font-size:13.5px">' + fmtRp(effP(p) * it.qty) + '</b><br/><button class="rm" data-prm="' + esc(p.id) + '"><i class="fa-solid fa-trash"></i></button></div></div>';
      }).join('');
    }
    $$('[data-pinc]', box).forEach(function (b) { b.onclick = function () { POS.add(b.dataset.pinc); }; });
    $$('[data-pdec]', box).forEach(function (b) {
      b.onclick = function () {
        var it = self.items.find(function (x) { return String(x.id) === b.dataset.pdec; });
        if (it) { it.qty--; if (it.qty <= 0) self.items = self.items.filter(function (x) { return x !== it; }); }
        self.renderCart();
      };
    });
    $$('[data-prm]', box).forEach(function (b) { b.onclick = function () { self.items = self.items.filter(function (x) { return String(x.id) !== b.dataset.prm; }); self.renderCart(); }; });
    this.totals();
  },
  subtotal() {
    var self = this;
    return this.items.reduce(function (s, it) {
      var p = DB.products.find(function (x) { return String(x.id) === String(it.id); });
      return s + (p ? effP(p) * it.qty : 0);
    }, 0);
  },
  discount() { return parseRp($('#pos-disc').value); },
  total() { return Math.max(0, this.subtotal() - this.discount()); },
  totals() {
    var sub = this.subtotal(), tot = this.total();
    $('#pos-sub').textContent = fmtRp(sub);
    $('#pos-total').textContent = fmtRp(tot);
    var cash = parseRp($('#pos-cash').value);
    $('#pos-change').textContent = fmtRp(Math.max(0, cash - tot));
    // quick cash
    var opts = [tot];
    [10000, 20000, 50000, 100000].forEach(function (den) {
      if (tot > 0) { var v = Math.ceil(tot / den) * den; if (opts.indexOf(v) === -1) opts.push(v); }
    });
    opts = opts.slice(0, 4).sort(function (a, b) { return a - b; });
    $('#pos-quick').innerHTML = (tot > 0 ? '<button data-u="1">Uang pas</button>' + opts.filter(function (v) { return v !== tot; }).slice(0, 3).map(function (v) { return '<button data-cash="' + v + '">' + (v >= 1000 ? (v / 1000) + 'rb' : v) + '</button>'; }).join('') : '');
    var u = $('#pos-quick [data-u]'); if (u) u.onclick = function () { $('#pos-cash').value = tot.toLocaleString('id-ID'); POS.totals(); };
    $$('#pos-quick [data-cash]').forEach(function (b) { b.onclick = function () { $('#pos-cash').value = Number(b.dataset.cash).toLocaleString('id-ID'); POS.totals(); }; });
  },
  renderPay() {
    var opts = [['cash', 'fa-money-bill-wave', 'Tunai'], ['qris', 'fa-qrcode', 'QRIS'], ['transfer', 'fa-building-columns', 'Transfer'], ['debit', 'fa-credit-card', 'Debit']];
    $('#pos-pay').innerHTML = opts.map(function (o) { return '<button data-pay="' + o[0] + '" class="' + (POS.pay === o[0] ? 'sel' : '') + '"><i class="fa-solid ' + o[1] + '"></i>' + o[2] + '</button>'; }).join('');
    $$('#pos-pay button').forEach(function (b) {
      b.onclick = function () {
        POS.pay = b.dataset.pay;
        $$('#pos-pay button').forEach(function (x) { x.classList.toggle('sel', x === b); });
        $('#pos-cashbox').style.display = POS.pay === 'cash' ? '' : 'none';
        POS.totals();
      };
    });
  },
  async pay() {
    if (!this.items.length) { toast('Belum ada item', 'warn'); return; }
    var tot = this.total();
    var cash = this.pay === 'cash' ? parseRp($('#pos-cash').value) : tot;
    if (this.pay === 'cash' && cash < tot) { toast('Uang tunai kurang ' + fmtRp(tot - cash), 'error'); return; }
    var btn = $('#btn-pos-pay'); btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Memproses…';
    var payload = {
      action: 'posCheckout', token: SESSION.token, cashier: SESSION.name || 'Kasir',
      customer_name: $('#pos-cust').value.trim() || 'Pelanggan',
      discount: this.discount(), payment_method: this.pay, pay: cash,
      items: this.items.map(function (it) { return { id: it.id, qty: it.qty }; })
    };
    try {
      var trx;
      if (Api.live) {
        trx = await Api.post(payload);
        try { var pr = await Api.get('getProducts', { limit: 100 }); DB.products = (pr.items || []).map(normProduct); } catch (e) {}
      } else {
        var lines = this.items.map(function (it) {
          var p = DB.products.find(function (x) { return String(x.id) === String(it.id); });
          return { id: p.id, name: p.name, price: effP(p), qty: it.qty, subtotal: effP(p) * it.qty };
        });
        trx = {
          id: uid('POS'), invoice: 'POS-20261007-' + Math.floor(1000 + Math.random() * 9000),
          date: new Date().toISOString(), customer_name: payload.customer_name,
          items: lines, subtotal: this.subtotal(), discount: this.discount(), total: tot,
          payment_method: this.pay, pay: cash, change: Math.max(0, cash - tot), cashier: payload.cashier
        };
        this.items.forEach(function (it) {
          var p = DB.products.find(function (x) { return String(x.id) === String(it.id); });
          p.stock = Math.max(0, p.stock - it.qty); p.sold = (p.sold || 0) + it.qty;
        });
      }
      this.items = [];
      $('#pos-cust').value = ''; $('#pos-disc').value = ''; $('#pos-cash').value = '';
      this.renderGrid(); this.renderCart();
      this.receipt(trx);
    } catch (err) { toast(err.message || 'Transaksi gagal', 'error'); }
    btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-money-bill-wave"></i> Bayar Sekarang';
  },
  receipt(t) {
    var items = t.items || [];
    try { if (!items.length && t.items_json) items = JSON.parse(t.items_json); } catch (e) {}
    openModal('<div class="receipt" id="struk"><h4>' + esc(SETTINGS.store_name) + '</h4><div class="c">' + esc(SETTINGS.store_address || '') + '<br/>' + esc(SETTINGS.store_wa || '') + '</div><hr/>' +
      '<div class="c">' + esc(t.invoice) + '<br/>' + fmtDate(t.date) + ' • ' + esc(t.cashier || 'Kasir') + '<br/>Yth: ' + esc(t.customer_name || 'Pelanggan') + '</div><hr/>' +
      items.map(function (it) { return esc(it.name) + '<br/>' + it.qty + ' x ' + fmtRp(it.price) + ' = <b>' + fmtRp(it.subtotal) + '</b>'; }).join('<br/>') + '<hr/>' +
      'Subtotal: ' + fmtRp(t.subtotal) + '<br/>Diskon: ' + fmtRp(t.discount || 0) + '<br/><b>TOTAL: ' + fmtRp(t.total) + '</b><br/>' +
      'Bayar (' + esc(t.payment_method || 'cash') + '): ' + fmtRp(t.pay || t.total) + '<br/><b>Kembali: ' + fmtRp(t.change || 0) + '</b><hr/>' +
      '<div class="c">Terima kasih telah berbelanja!<br/>Garansi &amp; info: ' + esc(SETTINGS.store_wa || '') + '<br/>*** LUNAS ***</div></div>' +
      '<div style="display:flex;gap:10px;margin-top:16px"><button class="btn btn-outline" style="flex:1" data-mx2="1">Tutup</button><button class="btn btn-primary" style="flex:1" id="rc-print"><i class="fa-solid fa-print"></i> Cetak Struk</button></div>');
    $('[data-mx2]').onclick = closeModal;
    $('#rc-print').onclick = function () {
      var w = window.open('', '_blank', 'width=360,height=600');
      w.document.write('<html><head><title>' + esc(t.invoice) + '</title><style>body{font-family:monospace;font-size:13px;max-width:300px;margin:10px auto}</style></head><body>' + $('#struk').innerHTML + '<script>window.onload=function(){window.print();}<\/script></body></html>');
      w.document.close();
    };
  },
  async history() {
    var list = [];
    if (Api.live) { try { var r = await Api.get('getOrders', { source: 'pos', limit: 50 }); list = r.items || r; } catch (e) {} }
    else list = DEMO.orders.filter(function (o) { return o.source === 'pos'; });
    openModal('<h3 style="margin-bottom:12px">Riwayat Transaksi POS</h3>' +
      (list.length ? '<div style="display:flex;flex-direction:column;gap:9px;max-height:60vh;overflow-y:auto">' + list.map(function (o) {
        return '<button class="citem" style="width:100%;text-align:left;cursor:pointer" data-h="' + esc(o.id) + '"><span class="ci"><b>' + esc(o.invoice) + '</b><span style="font-size:12.5px;color:var(--muted)">' + fmtDate(o.date || o.created_at) + ' • ' + esc(o.customer_name || '') + '</span></span><b>' + fmtRp(o.total) + '</b></button>';
      }).join('') + '</div>' : '<div class="empty"><i class="fa-solid fa-receipt"></i><p>Belum ada transaksi.</p></div>'), { lg: true });
    $$('#modal [data-h]').forEach(function (b) {
      b.onclick = function () {
        var o = list.find(function (x) { return String(x.id) === b.dataset.h; });
        try { o.items = JSON.parse(o.items_json); } catch (e) {}
        POS.receipt(o);
      };
    });
  },
  async today() {
    var d;
    if (Api.live) { try { d = await Api.get('getDashboard', {}); } catch (e) { d = null; } }
    if (!d) d = await adminDash();
    openModal('<h3 style="margin-bottom:12px">Ringkasan Hari Ini</h3><div class="stat-grid" style="grid-template-columns:1fr 1fr">' +
      '<div class="stat"><span class="si" style="background:linear-gradient(135deg,#059669,#34d399)"><i class="fa-solid fa-sack-dollar"></i></span><span><b>' + fmtRp(d.today_revenue) + '</b><span>Omzet hari ini</span></span></div>' +
      '<div class="stat"><span class="si" style="background:linear-gradient(135deg,#2563eb,#7c3aed)"><i class="fa-solid fa-receipt"></i></span><span><b>' + d.today_orders + '</b><span>Transaksi</span></span></div></div>' +
      '<p style="color:var(--muted);font-size:13.5px">Kasir: <b>' + esc(SESSION.name || '-') + '</b> • ' + new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) + '</p>');
  }
};

/* ================= INIT ================= */
async function boot() {
  document.body.dataset.route = 'store';
  // skeleton katalog
  $('#pgrid').innerHTML = Array(8).fill('<div><div class="sk" style="height:170px"></div><div class="sk" style="height:16px;margin-top:10px"></div><div class="sk" style="height:16px;width:60%;margin-top:8px"></div></div>').join('');
  await Store.init();
  applySettings();
  renderStorefront();
  Cart.badge(); Wishlist.badge(); renderDrawer();
  // filter events
  $('#q').addEventListener('input', debounce(function (e) { F.q = e.target.value; F.page = 1; renderProducts(); }, 350));
  $('#f-cond').onchange = function (e) { F.cond = e.target.value; F.page = 1; renderProducts(); };
  $('#f-sort').onchange = function (e) { F.sort = e.target.value; F.page = 1; renderProducts(); };
  $('#btn-more').onclick = function () { F.page++; renderProducts(); };
  // drawer & menu
  $('#btn-cart').onclick = openDrawer; $('#fab-cart').onclick = openDrawer;
  $('#btn-drawer-x').onclick = closeDrawer;
  $('#scrim').onclick = function () { closeDrawer(); closeModal(); };
  $('#btn-wish').onclick = function () { Wishlist.open(); };
  $('#btn-menu').onclick = function () { $('#mmenu').classList.add('open'); };
  $$('#mmenu [data-close-menu]').forEach(function (b) { b.onclick = function () { $('#mmenu').classList.remove('open'); }; });
  $$('#mmenu a.mlink').forEach(function (a) { a.addEventListener('click', function () { $('#mmenu').classList.remove('open'); }); });
  // form
  $('#trade-form').addEventListener('submit', submitTrade);
  $('#track-form').addEventListener('submit', trackOrder);
  $('#login-form').addEventListener('submit', function (e) { Admin.login(e); });
  $('#pos-login-form').addEventListener('submit', function (e) { POS.login(e); });
  $('#btn-logout').onclick = function (e) { e.preventDefault(); Admin.logout(); };
  $('#btn-aside').onclick = function () { $('#aside').classList.toggle('open'); };
  var asideBtn = function () { $('#btn-aside').style.display = window.innerWidth <= 920 ? '' : 'none'; };
  window.addEventListener('resize', asideBtn); asideBtn();
  // pos events
  $('#pos-q').addEventListener('input', debounce(function (e) { POS.q = e.target.value; POS.renderGrid(); }, 250));
  $('#pos-disc').addEventListener('input', function () { POS.totals(); });
  $('#pos-cash').addEventListener('input', function () { POS.totals(); });
  $('#btn-pos-pay').onclick = function () { POS.pay(); };
  $('#btn-pos-clear').onclick = function () { POS.items = []; POS.renderCart(); };
  $('#btn-pos-history').onclick = function () { POS.history(); };
  $('#btn-pos-today').onclick = function () { POS.today(); };
  document.addEventListener('keydown', function (e) {
    if (ROUTE === 'pos' && e.key === 'Enter' && document.activeElement === $('#pos-q')) {
      var list = POS.filtered();
      if (list.length === 1) { POS.add(list[0].id); $('#pos-q').value = ''; POS.q = ''; POS.renderGrid(); }
    }
  });
  router();
  observeRv();
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
//
